        float_bits_mantissa := autocast (T := mword) (subrange_vec_dec (op) (9) (0)) |}
   else if Z.eqb n (32) then
     {| float_bits_sign := subrange_vec_dec (op) (31) (31);
        float_bits_exp := autocast (T := mword) (subrange_vec_dec (op) (30) (23));
        float_bits_mantissa := autocast (T := mword) (subrange_vec_dec (op) (22) (0)) |}
   else if Z.eqb n (64) then
     {| float_bits_sign := subrange_vec_dec (op) (63) (63);
        float_bits_exp := autocast (T := mword) (subrange_vec_dec (op) (62) (52));
        float_bits_mantissa := autocast (T := mword) (subrange_vec_dec (op) (51) (0)) |}
   else
     {| float_bits_sign := subrange_vec_dec (op) (127) (127);
        float_bits_exp := autocast (T := mword) (subrange_vec_dec (op) (126) (112));
        float_bits_mantissa := autocast (T := mword) (subrange_vec_dec (op) (111) (0)) |}.

