     orb ((andb (is_neg) ((negb (unsigned_lt))))) ((andb ((negb (is_neg))) (unsigned_lt))) in
   let same_sign_lt := andb ((neq_vec (op_0) (op_1))) (is_xor) in
   if neq_vec (fp_0.(float_bits_sign)) (fp_1.(float_bits_sign)) then diff_sign_lt
   else same_sign_lt.

