   let is_rne := eq_vec (rounding_mode) (fp_rounding_rne) in
   let is_rna := eq_vec (rounding_mode) (fp_rounding_rna) in
   let not_rne_and_rna := andb ((negb (is_rne))) ((negb (is_rna))) in
   let rounding_inf :=
