Definition _update_RVFI_DII_Execution_PacketV2_trap_data_available (v : mword 512) (x : mword 1)
: mword 512 :=
   update_subrange_vec_dec (v) (454) (454) (x).

Definition _set_RVFI_DII_Execution_PacketV2_trap_data_available
(r_ref : register_ref (mword 512)) (v : mword 1)
: M (unit) :=
   (reg_deref (r_ref)) >>= fun r =>
   write_reg_ref r_ref (_update_RVFI_DII_Execution_PacketV2_trap_data_available (r) (v))
    : M (unit).

Definition _get_RVFI_DII_Execution_PacketV2_unused_data_available_fields (v : mword 512) : mword 57 :=
   subrange_vec_dec (v) (511) (455).

Definition _update_RVFI_DII_Execution_PacketV2_unused_data_available_fields
(v : mword 512) (x : mword 57)
: mword 512 :=
   update_subrange_vec_dec (v) (511) (455) (x).

Definition _set_RVFI_DII_Execution_PacketV2_unused_data_available_fields
(r_ref : register_ref (mword 512)) (v : mword 57)
: M (unit) :=
