    : M (unit).

Definition rvfi_get_v2_support_packet '(tt : unit) : mword 704 :=
   let rvfi_exec := Mk_RVFI_DII_Execution_Packet_V1 ((zeros' (704))) in
   _update_RVFI_DII_Execution_Packet_V1_rvfi_halt (rvfi_exec) ((Ox"03")).

Definition rvfi_get_v2_trace_size '(tt : unit) : M (mword 64) :=
   let trace_size : bits 64 := to_bits (64) (512) in
   read_reg rvfi_int_data_present >>= fun (w__0 : bool) =>
   let trace_size := if w__0 then add_vec_int (trace_size) (320) else trace_size in
   read_reg rvfi_mem_data_present >>= fun (w__1 : bool) =>
   let trace_size := if w__1 then add_vec_int (trace_size) (704) else trace_size in
   returnM ((shiftr (trace_size) (3))).

Definition rvfi_get_exec_packet_v2 '(tt : unit) : M (mword 512) :=
   let packet := Mk_RVFI_DII_Execution_PacketV2 ((zeros' (512))) in
   let packet := _update_RVFI_DII_Execution_PacketV2_magic (packet) ((Ox"32762D6563617274")) in
   ((read_reg rvfi_inst_data)  : M (mword 192)) >>= fun (w__0 : mword 192) =>
   let packet := _update_RVFI_DII_Execution_PacketV2_basic_data (packet) (w__0) in
   ((read_reg rvfi_pc_data)  : M (mword 128)) >>= fun (w__1 : mword 128) =>
   let packet := _update_RVFI_DII_Execution_PacketV2_pc_data (packet) (w__1) in
   read_reg rvfi_int_data_present >>= fun (w__2 : bool) =>
   let packet :=
     _update_RVFI_DII_Execution_PacketV2_integer_data_available (packet) ((bool_to_bit (w__2))) in
   read_reg rvfi_mem_data_present >>= fun (w__3 : bool) =>
   let packet :=
     _update_RVFI_DII_Execution_PacketV2_memory_access_data_available (packet)
       ((bool_to_bit (w__3))) in
   (rvfi_get_v2_trace_size (tt)) >>= fun (w__4 : mword 64) =>
   let packet := _update_RVFI_DII_Execution_PacketV2_trace_size (packet) (w__4) in
   returnM (packet).

