Definition undefined_misaligned_exception '(tt : unit) : M (misaligned_exception) :=
   (internal_pick ([AccessFault; AlignmentException]))  : M (misaligned_exception).

Definition misaligned_exception_str_forwards (arg_ : misaligned_exception) : string :=
   match arg_ with | AccessFault => "AccessFault" | AlignmentException => "AlignmentException" end.

Definition misaligned_exception_str_backwards (arg_ : string) : M (misaligned_exception) :=
   let p0_ := arg_ in
   (if generic_eq (p0_) ("AccessFault") then returnM (AccessFault)
    else if generic_eq (p0_) ("AlignmentException") then returnM (AlignmentException)
    else assert_exp' false "Pattern match failure at unknown location" >>= fun _ => exit tt)
    : M (misaligned_exception).

Definition misaligned_exception_str_forwards_matches (arg_ : misaligned_exception) : bool :=
   match arg_ with | AccessFault => true | AlignmentException => true end.

Definition misaligned_exception_str_backwards_matches (arg_ : string) : bool :=
   let p0_ := arg_ in
   if generic_eq (p0_) ("AccessFault") then true
   else if generic_eq (p0_) ("AlignmentException") then true
   else false.

Definition mem_payload_str_forwards (arg_ : mem_payload) : string :=
   match arg_ with | Data => "" | Vector => "" | PageTableEntry => "" | ShadowStack => ".ss" end.

Definition sp : regidx := Regidx ((zero_extend' (5) (('b"10")))).
#[export] Hint Unfold sp : sail.
Definition accessType_to_str (access : MemoryAccessType mem_payload) : string :=
   match access with
   | Load p => String.append ("R") ((mem_payload_str_forwards (p)))
   | LoadReserved (_, _, p) => String.append ("R") ((mem_payload_str_forwards (p)))
   | Store p => String.append ("W") ((mem_payload_str_forwards (p)))
   | StoreConditional (_, _, p) => String.append ("W") ((mem_payload_str_forwards (p)))
   | Atomic (_, _, _, lp, sp) =>
      String.append ("R")
        ((String.append ((mem_payload_str_forwards (lp)))
            ((String.append ("W") ((mem_payload_str_forwards (sp)))))))
   | InstructionFetch tt => "X"
   | LoadExecute p => String.append ("RX") ((mem_payload_str_forwards (p)))
   | CacheAccess _ => "C"
   end.

Definition atomic_support_str_backwards (arg_ : string) : M (AtomicSupport) :=
   let p0_ := arg_ in
   (if generic_eq (p0_) ("AMONone") then returnM (AMONone)
    else if generic_eq (p0_) ("AMOSwap") then returnM (AMOSwap)
    else if generic_eq (p0_) ("AMOLogical") then returnM (AMOLogical)
    else if generic_eq (p0_) ("AMOArithmetic") then returnM (AMOArithmetic)
    else if generic_eq (p0_) ("AMOCASW") then returnM (AMOCASW)
    else if generic_eq (p0_) ("AMOCASD") then returnM (AMOCASD)
    else if generic_eq (p0_) ("AMOCASQ") then returnM (AMOCASQ)
    else assert_exp' false "Pattern match failure at unknown location" >>= fun _ => exit tt)
    : M (AtomicSupport).

Definition atomic_support_str_forwards (arg_ : AtomicSupport) : string :=
   match arg_ with
   | AMONone => "AMONone"
   | AMOSwap => "AMOSwap"
   | AMOLogical => "AMOLogical"
   | AMOArithmetic => "AMOArithmetic"
   | AMOCASW => "AMOCASW"
   | AMOCASD => "AMOCASD"
   | AMOCASQ => "AMOCASQ"
   end.

