Definition csr_name (csr : mword 12) : M (string) := (csr_name_map_forwards (csr))  : M (string).

Definition ext_exc_type_to_str (_e : unit) : string := "extension-exception".

Definition exceptionType_to_str (e : ExceptionType) : string :=
   match e with
   | E_Fetch_Addr_Align tt => "misaligned-fetch"
   | E_Fetch_Access_Fault tt => "fetch-access-fault"
   | E_Illegal_Instr tt => "illegal-instruction"
   | E_Load_Addr_Align tt => "misaligned-load"
   | E_Load_Access_Fault tt => "load-access-fault"
   | E_SAMO_Addr_Align tt => "misaligned-store/amo"
   | E_SAMO_Access_Fault tt => "store/amo-access-fault"
   | E_U_EnvCall tt => "u-call"
   | E_S_EnvCall tt => "s-call"
   | E_VS_EnvCall tt => "vs-call"
   | E_M_EnvCall tt => "m-call"
   | E_Fetch_Page_Fault tt => "fetch-page-fault"
   | E_Load_Page_Fault tt => "load-page-fault"
   | E_Reserved_14 tt => "reserved-1"
   | E_SAMO_Page_Fault tt => "store/amo-page-fault"
   | E_Double_Trap tt => "double-trap"
   | E_Reserved_17 tt => "reserved-3"
   | E_Software_Check tt => "software-check-exception"
   | E_Hardware_Error tt => "hardware-error-exception"
   | E_Fetch_GPage_Fault tt => "fetch-guest-page-fault"
   | E_Load_GPage_Fault tt => "load-guest-page-fault"
   | E_Virtual_Instr tt => "virtual-instruction"
   | E_SAMO_GPage_Fault tt => "store/amo-guest-page-fault"
   | E_Breakpoint Brk_Software => "software-breakpoint"
   | E_Breakpoint Brk_Hardware => "hardware-breakpoint"
   | E_Extension e => ext_exc_type_to_str (e)
   end.

Definition bitype_mnemonic_forwards (arg_ : biop) : string :=
   match arg_ with | BEQI => "beqi" | BNEI => "bnei" end.

Definition btype_mnemonic_forwards (arg_ : bop) : string :=
   match arg_ with
   | BEQ => "beq"
   | BNE => "bne"
   | BLT => "blt"
   | BGE => "bge"
   | BLTU => "bltu"
   | BGEU => "bgeu"
   end.

Definition cbop_mnemonic_forwards (arg_ : cbop_zicbom) : string :=
   match arg_ with
   | CBO_CLEAN => "cbo.clean"
   | CBO_FLUSH => "cbo.flush"
   | CBO_INVAL => "cbo.inval"
   end.

