Definition freg_name_forwards (arg_ : fregidx) : M (string) :=
   match arg_ with
   | Fregidx i =>
      (if get_config_use_abi_names (tt) then returnM ((freg_abi_name_raw_forwards (i)))
       else if not ((get_config_use_abi_names (tt))) then
         returnM ((freg_arch_name_raw_forwards (i)))
       else assert_exp' false "Pattern match failure at unknown location" >>= fun _ => exit tt)
       : M (string)
   end
    : M (string).

Definition cfreg_name_forwards (arg_ : cfregidx) : M (string) :=
   match arg_ with
   | Cfregidx i =>
      (freg_name_forwards ((Fregidx ((concat_vec (('b"01")) ((i  : mword 3)))))))  : M (string)
   end
    : M (string).

Definition base_E_enabled := false.
#[export] Hint Unfold base_E_enabled : sail.
Definition regidx_bit_width := 5.
#[export] Hint Unfold regidx_bit_width : sail.
Definition encdec_reg_backwards (arg_ : mword 5) : M (regidx) :=
   let r := arg_ in
   (if orb ((not (base_E_enabled))) ((eq_vec ((access_vec_dec (r) (4))) (('b"0")))) then
      returnM ((Regidx
                  ((autocast (T := mword)
                    (subrange_vec_dec (r) ((Z.sub (regidx_bit_width) (1))) (0))))))
    else assert_exp' false "Pattern match failure at unknown location" >>= fun _ => exit tt)
    : M (regidx).

