Definition reg_name_forwards (arg_ : regidx) : M (string) :=
   let head_exp_ := arg_ in
   let mapping0_ := head_exp_ in
   match if encdec_reg_forwards_matches (mapping0_) then
           let i := encdec_reg_forwards (mapping0_) in
           if get_config_use_abi_names (tt) then Some ((reg_abi_name_raw_forwards (i)))
           else None
         else None with
   | Some result' => returnM (result')
   | None =>
      let mapping1_ := head_exp_ in
      match if encdec_reg_forwards_matches (mapping1_) then
              let i := encdec_reg_forwards (mapping1_) in
              if not ((get_config_use_abi_names (tt))) then Some ((reg_arch_name_raw_forwards (i)))
              else None
            else None with
      | Some result' => returnM (result')
      | _ => assert_exp' false "Pattern match failure at unknown location" >>= fun _ => exit tt
      end
       : M (string)
   end
    : M (string).

Definition creg_name_forwards (arg_ : cregidx) : M (string) :=
   match arg_ with
   | Cregidx i =>
      (encdec_reg_backwards ((concat_vec (('b"01")) ((i  : mword 3))))) >>= fun (w__0 : regidx) =>
      (reg_name_forwards (w__0))
       : M (string)
   end
    : M (string).

