   else String.append ((sep_forwards (tt))) ((String.append ("tu") (""))).

Definition vtr_mnemonic_forwards (_vtr : mword 3) : string := "".

Definition vtype_assembly_forwards (arg_ : (mword 3 * mword 1 * mword 1 * mword 3 * mword 3))
: M (string) :=
   match arg_ with
   | (vtr, ma, ta, sew, lmul) =>
      (if andb ((neq_vec ((access_vec_dec (sew) (2))) (('b"1"))))
            ((andb ((neq_vec (lmul) (('b"100")))) ((eq_vec (vtr) (('b"000"))))))
         return
         M (string) then
         (sew_flag_backwards (sew)) >>= fun (w__0 : string) =>
         (maybe_lmul_flag_backwards (lmul)) >>= fun (w__1 : string) =>
         returnM ((String.append (w__0)
                     ((String.append (w__1)
                         ((String.append ((ta_flag_backwards (ta)))
                             ((String.append ((ma_flag_backwards (ma)))
                                 ((String.append ((vtr_mnemonic_forwards (vtr))) ("")))))))))))
       else
         (hex_bits_11_forwards
            ((concat_vec ((vtr  : mword 3))
                ((concat_vec ((ma  : mword 1))
                    ((concat_vec ((ta  : mword 1))
                        ((concat_vec ((sew  : mword 3)) ((lmul  : mword 3)))))))))))
          : M (string))
       : M (string)
   end
    : M (string).

