Definition zilx_encoding_valid (mode : zilx_mode) (width : Z) (is_unsigned : bool)
(*member_Z_list width [1; 2; 4; 8]*)
: bool :=
   andb ((valid_load_encdec (width) (is_unsigned)))
     ((andb ((orb ((generic_neq (mode) (ZILX_UNSCALED))) ((neq_int (width) (1)))))
         ((orb ((generic_neq (mode) (ZILX_SCALED_UW))) ((Z.eqb (xlen) (64))))))).

