#[export] Hint Unfold xenvcfg_cbie_reserved_behavior : sail.
Definition legalize_xenvcfg_cbie (old_cbie : mword 2) (new_cbie : mword 2) : M (mword 2) :=
   (if neq_vec (new_cbie) (('b"10")) then returnM (new_cbie)
    else
      match xenvcfg_cbie_reserved_behavior with
      | Xenvcfg_Fatal => (reserved_behavior ("xenvcfg.CBIE = 0b10"))  : M (mword 2)
      | Xenvcfg_ClearPermissions => returnM (('b"00"))
      | Xenvcfg_Ignore => returnM (old_cbie)
      end
       : M (mword 2))
    : M (mword 2).

