   (is_mstateen_accessible (tt)) >>= fun (w__0 : bool) =>
   (if not (w__0) then returnM ((ones (64)))
    else
      let l__0 := idx in
      (if Z.eqb (l__0) (0) return M (mword 64) then
         ((read_reg mstateen0)  : M (mword 64))
          : M (mword 64)
       else if Z.eqb (l__0) (1) return M (mword 64) then
         ((read_reg mstateen1)  : M (mword 64))
          : M (mword 64)
       else if Z.eqb (l__0) (2) return M (mword 64) then
         ((read_reg mstateen2)  : M (mword 64))
          : M (mword 64)
       else ((read_reg mstateen3)  : M (mword 64))  : M (mword 64))
       : M (mword 64))
    : M (mword 64).

