Fixpoint _rec_check_stateen_bit
(priv : Privilege) (bit_idx : stateen_bit) (stateen_reg : Z) (_reclimit : Z)
(*(0 <=? stateen_reg) && (stateen_reg <=? 3)*) (_acc : Acc (Zwf 0) _reclimit)
{struct _acc} : M (bool)
with _rec_currentlyEnabled (merge_var : extension) (_reclimit : Z) (_acc : Acc (Zwf 0) _reclimit)
{struct _acc} : M (bool)
with _rec_get_hstateen (idx : Z) (_reclimit : Z) (*(0 <=? idx) && (idx <=? 3)*)
(_acc : Acc (Zwf 0) _reclimit)
{struct _acc} : M (mword 64)
with _rec_get_sstateen (idx : Z) (_reclimit : Z) (*(0 <=? idx) && (idx <=? 3)*)
(_acc : Acc (Zwf 0) _reclimit)
{struct _acc} : M (mword 64)
with _rec_get_xLPE (p : Privilege) (_reclimit : Z) (_acc : Acc (Zwf 0) _reclimit)
{struct _acc} : M (bool)
with _rec_is_hstateen_accessible (arg0 : unit) (_reclimit : Z) (_acc : Acc (Zwf 0) _reclimit)
{struct _acc} : M (bool)
with _rec_is_sstateen_accessible (arg0 : unit) (_reclimit : Z) (_acc : Acc (Zwf 0) _reclimit)
{struct _acc} : M (bool)
with _rec_is_zfinx_enabled_by_stateen (arg0 : unit) (_reclimit : Z) (_acc : Acc (Zwf 0) _reclimit)
{struct _acc} : M (bool).
(*#rec#check_stateen_bit*) exact (
   assert_exp' (Z.geb (_reclimit) (0)) "recursion limit reached" >>= fun _ =>
   match priv with
   | Machine => returnM ((ones (64)))
   | Supervisor => (get_mstateen (stateen_reg))  : M (mword 64)
   | User =>
      (get_mstateen (stateen_reg)) >>= fun (w__1 : mword 64) =>
      (_rec_get_sstateen (stateen_reg) ((Z.sub (_reclimit) (1)))
         (_limit_reduces_bool _acc ltac:(assumption))) >>= fun (w__2 : mword 64) =>
      returnM ((and_vec (w__1) (w__2)))
   | VirtualSupervisor =>
      (get_mstateen (stateen_reg)) >>= fun (w__3 : mword 64) =>
      (_rec_get_hstateen (stateen_reg) ((Z.sub (_reclimit) (1)))
         (_limit_reduces_bool _acc ltac:(assumption))) >>= fun (w__4 : mword 64) =>
      returnM ((and_vec (w__3) (w__4)))
   | VirtualUser =>
      (get_mstateen (stateen_reg)) >>= fun (w__5 : mword 64) =>
      (_rec_get_hstateen (stateen_reg) ((Z.sub (_reclimit) (1)))
         (_limit_reduces_bool _acc ltac:(assumption))) >>= fun (w__6 : mword 64) =>
      (_rec_get_sstateen (stateen_reg) ((Z.sub (_reclimit) (1)))
         (_limit_reduces_bool _acc ltac:(assumption))) >>= fun (w__7 : mword 64) =>
      returnM ((and_vec (w__5) ((and_vec (w__6) (w__7)))))
   end >>= fun (mask : bits 64) =>
   returnM ((eq_vec ((access_vec_dec (mask) ((stateen_bit_index_forwards (bit_idx))))) (('b"1"))))
).
(*#rec#currentlyEnabled*) exact (
   assert_exp' (Z.geb (_reclimit) (0)) "recursion limit reached" >>= fun _ =>
   match merge_var with
   | Ext_Shcounterenw =>
      (and_boolM ((hartSupports (Ext_Shcounterenw))  : M (bool))
