Definition amo_encoding_valid
(width : Z) (op : amoop) '((Regidx rs2) : regidx) '((Regidx rd) : regidx)
(*member_Z_list width [1; 2; 4; 8; 16]*)
: M (bool) :=
   (and_boolM
      ((if generic_eq (op) (AMOCAS) return M (bool) then (currentlyEnabled (Ext_Zacas))  : M (bool)
        else (currentlyEnabled (Ext_Zaamo))  : M (bool))
       : M (bool))
      ((if Z.ltb (width) (4) return M (bool) then (currentlyEnabled (Ext_Zabha))  : M (bool)
        else
          or_boolM (returnM ((Z.leb (width) (xlen_bytes))))
            (and_boolM
               (returnM ((andb ((generic_eq (op) (AMOCAS)))
                            ((Z.leb (width) ((Z.mul (xlen_bytes) (2))))))))
               ((if orb ((eq_vec ((access_vec_dec (rs2) (0))) (('b"1"))))
                      ((eq_vec ((access_vec_dec (rd) (0))) (('b"1"))))
                   return
                   M (bool) then
                   match amocas_odd_register_reserved_behavior with
                   | AMOCAS_Fatal =>
                      (reserved_behavior
                         ((String.append ("AMOCAS.D/Q used an odd-numbered register (rs2 = ")
                             ((String.append ((dec_str ((uint (rs2)))))
                                 ((String.append (", rd = ")
                                     ((String.append ((dec_str ((uint (rd))))) (")."))))))))))
                       : M (bool)
                   | AMOCAS_Illegal => returnM (false)
                   end
                    : M (bool)
                 else returnM (true))
                : M (bool))))
       : M (bool)))
    : M (bool).

