Definition _get_Vtype_vlmul (v : mword 64) : mword 3 := subrange_vec_dec (v) (2) (0).

Definition get_lmul_pow '(tt : unit) : M (Z) :=
   ((read_reg vtype)  : M (mword 64)) >>= fun (w__0 : mword 64) =>
   let lmul_pow := sint ((_get_Vtype_vlmul (w__0))) in
   assert_exp' (Z.gtb (lmul_pow) ((Z.opp (4)))) "Reserved LMUL stored in vtype register. This should be impossible." >>= fun _ =>
   returnM (lmul_pow).

Definition _get_Vtype_vsew (v : mword 64) : mword 3 := subrange_vec_dec (v) (5) (3).

