Definition architecture_bits_backwards (arg_ : mword 2) : M (Architecture) :=
   let p0_ := arg_ in
   (if eq_vec (p0_) (('b"01")) then returnM (RV32)
    else if eq_vec (p0_) (('b"10")) then returnM (RV64)
    else if eq_vec (p0_) (('b"11")) then returnM (RV128)
    else
      (internal_error ("core/types.sail") (62) ("architecture(0b00) is invalid"))
       : M (Architecture))
    : M (Architecture).

Definition architecture (priv : Privilege) : M (Architecture) :=
   match priv with
   | Machine =>
      ((read_reg misa)  : M (mword 64)) >>= fun (w__0 : mword 64) =>
      returnM ((_get_Misa_MXL (w__0)))
   | Supervisor =>
      ((read_reg mstatus)  : M (mword 64)) >>= fun (w__1 : mword 64) =>
      returnM ((_get_Mstatus_SXL (w__1)))
   | User =>
      ((read_reg mstatus)  : M (mword 64)) >>= fun (w__2 : mword 64) =>
      returnM ((_get_Mstatus_UXL (w__2)))
   | VirtualSupervisor =>
      ((read_reg hstatus)  : M (mword 64)) >>= fun (w__3 : mword 64) =>
      returnM ((_get_Hstatus_VSXL (w__3)))
   | VirtualUser =>
      ((read_reg vsstatus)  : M (mword 64)) >>= fun (w__4 : mword 64) =>
      returnM ((_get_Mstatus_UXL (w__4)))
   end >>= fun (w__5 : mword 2) =>
   (architecture_bits_backwards (w__5))
    : M (Architecture).

