Definition translationStage_to_str (stage : TranslationStage) : string :=
   match stage with | S_Stage => "S_Stage" | VS_Stage => "VS_Stage" | G_Stage => "G_Stage" end.

Definition trapCause_to_str (t : TrapCause) : string :=
   match t with
   | Interrupt i => String.append ("int#") ((interruptType_to_str (i)))
   | Exception e => String.append ("exc#") ((exceptionType_to_str (e.(ExceptionContext_trap))))
   end.

