Definition init_ext_ptw : ext_ptw := tt.
#[export] Hint Unfold init_ext_ptw : sail.
Definition ext_translate_exception (e : unit) : unit := e.

Definition ext_exc_type_bits_forwards (arg_ : unit) : mword 6 :=
   match arg_ with | tt => ('b"011000") end.

Definition ext_exc_type_bits_backwards (arg_ : mword 6) : M (unit) :=
   let p0_ := arg_ in
   (if eq_vec (p0_) (('b"011000")) then returnM (tt)
    else assert_exp' false "Pattern match failure at unknown location" >>= fun _ => exit tt)
    : M (unit).

Definition ext_exc_type_bits_forwards_matches (arg_ : unit) : bool :=
   match arg_ with | tt => true end.

Definition ext_exc_type_bits_backwards_matches (arg_ : mword 6) : bool :=
   let p0_ := arg_ in
   if eq_vec (p0_) (('b"011000")) then true
   else false.

Definition pagesize_bits := 12.
#[export] Hint Unfold pagesize_bits : sail.
Definition regidx_bits '((Regidx b) : regidx) : mword ((if base_E_enabled then 4 else 5)) := b.

Definition creg2reg_idx '((Cregidx i) : cregidx) : regidx :=
   Regidx ((zero_extend' (5) ((concat_vec (('b"1")) (i))))).

Definition undefined_Architecture '(tt : unit) : M (Architecture) :=
   (internal_pick ([RV32; RV64; RV128]))  : M (Architecture).

Definition architecture_bits_forwards_matches (arg_ : Architecture) : bool :=
   match arg_ with | RV32 => true | RV64 => true | RV128 => true end.

Definition architecture_bits_backwards_matches (arg_ : mword 2) : bool :=
   let p0_ := arg_ in
   if eq_vec (p0_) (('b"01")) then true
   else if eq_vec (p0_) (('b"10")) then true
   else if eq_vec (p0_) (('b"11")) then true
   else if eq_vec (p0_) (('b"00")) then true
   else false.

Definition privLevel_bits_forwards (arg_ : (mword 2 * mword 1)) : M (Privilege) :=
   match arg_ with
   | (p0_, p1_) =>
      (if andb ((eq_vec (p1_) (('b"0")))) ((eq_vec (p0_) (('b"00")))) then returnM (User)
       else if andb ((eq_vec (p1_) (('b"1")))) ((eq_vec (p0_) (('b"00")))) then
         returnM (VirtualUser)
       else if andb ((eq_vec (p1_) (('b"0")))) ((eq_vec (p0_) (('b"01")))) then returnM (Supervisor)
       else if andb ((eq_vec (p1_) (('b"1")))) ((eq_vec (p0_) (('b"01")))) then
         returnM (VirtualSupervisor)
       else if andb ((eq_vec (p1_) (('b"0")))) ((eq_vec (p0_) (('b"11")))) then returnM (Machine)
       else
         (internal_error ("core/types.sail") (79) ("Invalid privilege level or virtual mode"))
          : M (Privilege))
       : M (Privilege)
   end
    : M (Privilege).

Definition privLevel_bits_backwards (arg_ : Privilege) : (mword 2 * mword 1) :=
   match arg_ with
   | User => ((('b"00"), ('b"0")))
   | VirtualUser => ((('b"00"), ('b"1")))
   | Supervisor => ((('b"01"), ('b"0")))
   | VirtualSupervisor => ((('b"01"), ('b"1")))
   | Machine => ((('b"11"), ('b"0")))
   end.

Definition privLevel_bits_forwards_matches (arg_ : (mword 2 * mword 1)) : bool :=
   match arg_ with
   | (p0_, p1_) =>
      if andb ((eq_vec (p1_) (('b"0")))) ((eq_vec (p0_) (('b"00")))) then true
      else if andb ((eq_vec (p1_) (('b"1")))) ((eq_vec (p0_) (('b"00")))) then true
      else if andb ((eq_vec (p1_) (('b"0")))) ((eq_vec (p0_) (('b"01")))) then true
      else if andb ((eq_vec (p1_) (('b"1")))) ((eq_vec (p0_) (('b"01")))) then true
      else if andb ((eq_vec (p1_) (('b"0")))) ((eq_vec (p0_) (('b"11")))) then true
      else true
   end.

Definition privLevel_bits_backwards_matches (arg_ : Privilege) : bool :=
   match arg_ with
   | User => true
   | VirtualUser => true
   | Supervisor => true
   | VirtualSupervisor => true
   | Machine => true
   end.

Definition privLevel_to_bits (p : Privilege) : mword 2 :=
   let '((p, _)) := privLevel_bits_backwards (p) in
   p.

Definition privLevel_to_virt_bit (p : Privilege) : mword 1 :=
   let '((_, v)) := privLevel_bits_backwards (p) in
   v.

Definition is_load_store {a : Type} (access : MemoryAccessType a) : bool :=
   match access with
   | Load _ => true
   | Store _ => true
   | LoadReserved _ => true
   | LoadExecute _ => true
   | StoreConditional _ => true
   | Atomic _ => true
   | InstructionFetch _ => false
   | CacheAccess _ => true
   end.

Definition is_prefetch_access {a : Type} (access : MemoryAccessType a) : bool :=
   match access with | CacheAccess (CB_prefetch _) => true | _ => false end.

Definition is_load_reserved {a : Type} (access : MemoryAccessType a) : bool :=
   match access with | LoadReserved _ => true | _ => false end.

Definition is_store_conditional {a : Type} (access : MemoryAccessType a) : bool :=
   match access with | StoreConditional _ => true | _ => false end.

Definition undefined_CSRAccessType '(tt : unit) : M (CSRAccessType) :=
   (internal_pick ([CSRRead; CSRWrite; CSRReadWrite]))  : M (CSRAccessType).

Definition undefined_InterruptType '(tt : unit) : M (InterruptType) :=
   (internal_pick
      ([I_Reserved_0;
      I_S_Software;
      I_VS_Software;
      I_M_Software;
      I_Reserved_4;
      I_S_Timer;
      I_VS_Timer;
      I_M_Timer;
      I_Reserved_8;
      I_S_External;
      I_VS_External;
      I_M_External;
      I_SG_External;
      I_COF;
      I_Reserved_14;
      I_Reserved_15]))
    : M (InterruptType).

Definition interruptType_bits_forwards (arg_ : InterruptType) : mword 6 :=
   match arg_ with
   | I_Reserved_0 => ('b"000000")
   | I_S_Software => ('b"000001")
   | I_VS_Software => ('b"000010")
   | I_M_Software => ('b"000011")
   | I_Reserved_4 => ('b"000100")
   | I_S_Timer => ('b"000101")
   | I_VS_Timer => ('b"000110")
   | I_M_Timer => ('b"000111")
   | I_Reserved_8 => ('b"001000")
   | I_S_External => ('b"001001")
   | I_VS_External => ('b"001010")
   | I_M_External => ('b"001011")
   | I_SG_External => ('b"001100")
   | I_COF => ('b"001101")
   | I_Reserved_14 => ('b"001110")
   | I_Reserved_15 => ('b"001111")
   end.

Definition interruptType_bits_backwards (arg_ : mword 6) : M (InterruptType) :=
   let p0_ := arg_ in
   (if eq_vec (p0_) (('b"000000")) then returnM (I_Reserved_0)
    else if eq_vec (p0_) (('b"000001")) then returnM (I_S_Software)
    else if eq_vec (p0_) (('b"000010")) then returnM (I_VS_Software)
    else if eq_vec (p0_) (('b"000011")) then returnM (I_M_Software)
    else if eq_vec (p0_) (('b"000100")) then returnM (I_Reserved_4)
    else if eq_vec (p0_) (('b"000101")) then returnM (I_S_Timer)
    else if eq_vec (p0_) (('b"000110")) then returnM (I_VS_Timer)
    else if eq_vec (p0_) (('b"000111")) then returnM (I_M_Timer)
    else if eq_vec (p0_) (('b"001000")) then returnM (I_Reserved_8)
    else if eq_vec (p0_) (('b"001001")) then returnM (I_S_External)
    else if eq_vec (p0_) (('b"001010")) then returnM (I_VS_External)
    else if eq_vec (p0_) (('b"001011")) then returnM (I_M_External)
    else if eq_vec (p0_) (('b"001100")) then returnM (I_SG_External)
    else if eq_vec (p0_) (('b"001101")) then returnM (I_COF)
    else if eq_vec (p0_) (('b"001110")) then returnM (I_Reserved_14)
    else if eq_vec (p0_) (('b"001111")) then returnM (I_Reserved_15)
    else assert_exp' false "Pattern match failure at unknown location" >>= fun _ => exit tt)
    : M (InterruptType).

Definition interruptType_bits_forwards_matches (arg_ : InterruptType) : bool :=
   match arg_ with
   | I_Reserved_0 => true
   | I_S_Software => true
   | I_VS_Software => true
   | I_M_Software => true
   | I_Reserved_4 => true
   | I_S_Timer => true
   | I_VS_Timer => true
   | I_M_Timer => true
   | I_Reserved_8 => true
   | I_S_External => true
   | I_VS_External => true
   | I_M_External => true
   | I_SG_External => true
   | I_COF => true
   | I_Reserved_14 => true
   | I_Reserved_15 => true
   end.

Definition interruptType_bits_backwards_matches (arg_ : mword 6) : bool :=
   let p0_ := arg_ in
   if eq_vec (p0_) (('b"000000")) then true
   else if eq_vec (p0_) (('b"000001")) then true
   else if eq_vec (p0_) (('b"000010")) then true
   else if eq_vec (p0_) (('b"000011")) then true
   else if eq_vec (p0_) (('b"000100")) then true
   else if eq_vec (p0_) (('b"000101")) then true
   else if eq_vec (p0_) (('b"000110")) then true
   else if eq_vec (p0_) (('b"000111")) then true
   else if eq_vec (p0_) (('b"001000")) then true
   else if eq_vec (p0_) (('b"001001")) then true
   else if eq_vec (p0_) (('b"001010")) then true
   else if eq_vec (p0_) (('b"001011")) then true
   else if eq_vec (p0_) (('b"001100")) then true
   else if eq_vec (p0_) (('b"001101")) then true
   else if eq_vec (p0_) (('b"001110")) then true
   else if eq_vec (p0_) (('b"001111")) then true
   else false.

Definition is_reserved_interrupt (i : InterruptType) : bool :=
   match i with
   | I_Reserved_0 => true
   | I_Reserved_4 => true
   | I_Reserved_8 => true
   | I_Reserved_14 => true
   | I_Reserved_15 => true
   | _ => false
   end.

Definition is_hypervisor_interrupt (i : InterruptType) : bool :=
   match i with
   | I_VS_Software => true
   | I_VS_Timer => true
   | I_VS_External => true
   | I_SG_External => true
   | _ => false
   end.

Definition undefined_breakpoint_cause '(tt : unit) : M (breakpoint_cause) :=
   (internal_pick ([Brk_Software; Brk_Hardware]))  : M (breakpoint_cause).

Definition exceptionType_bits_forwards (arg_ : ExceptionType) : mword 6 :=
   match arg_ with
   | E_Fetch_Addr_Align tt => ('b"000000")
   | E_Fetch_Access_Fault tt => ('b"000001")
   | E_Illegal_Instr tt => ('b"000010")
   | E_Load_Addr_Align tt => ('b"000100")
   | E_Load_Access_Fault tt => ('b"000101")
   | E_SAMO_Addr_Align tt => ('b"000110")
   | E_SAMO_Access_Fault tt => ('b"000111")
   | E_U_EnvCall tt => ('b"001000")
   | E_S_EnvCall tt => ('b"001001")
   | E_VS_EnvCall tt => ('b"001010")
   | E_M_EnvCall tt => ('b"001011")
   | E_Fetch_Page_Fault tt => ('b"001100")
   | E_Load_Page_Fault tt => ('b"001101")
   | E_Reserved_14 tt => ('b"001110")
   | E_SAMO_Page_Fault tt => ('b"001111")
   | E_Double_Trap tt => ('b"010000")
   | E_Reserved_17 tt => ('b"010001")
   | E_Software_Check tt => ('b"010010")
   | E_Hardware_Error tt => ('b"010011")
   | E_Fetch_GPage_Fault tt => ('b"010100")
   | E_Load_GPage_Fault tt => ('b"010101")
   | E_Virtual_Instr tt => ('b"010110")
   | E_SAMO_GPage_Fault tt => ('b"010111")
   | E_Breakpoint Brk_Software => ('b"000011")
   | E_Breakpoint Brk_Hardware => ('b"000011")
   | E_Extension e => ext_exc_type_bits_forwards (e)
   end.

Definition exceptionType_bits_backwards (arg_ : mword 6) : M (ExceptionType) :=
   let head_exp_ := arg_ in
   let p0_ := head_exp_ in
   (if eq_vec (p0_) (('b"000000")) then returnM ((Some ((E_Fetch_Addr_Align (tt)))))
    else if eq_vec (p0_) (('b"000001")) then returnM ((Some ((E_Fetch_Access_Fault (tt)))))
    else if eq_vec (p0_) (('b"000010")) then returnM ((Some ((E_Illegal_Instr (tt)))))
    else if eq_vec (p0_) (('b"000100")) then returnM ((Some ((E_Load_Addr_Align (tt)))))
