     {| ExceptionContext_trap := E_Load_Addr_Align tt; ExceptionContext_ext := _; ExceptionContext_excinst_offset := _; ExceptionContext_excinst := _; ExceptionContext_excinfo_is_gva := _; ExceptionContext_excinfo2 := _; ExceptionContext_excinfo := _ |} =>
      (generate_event (EV_MISALIGNED_LOAD_EXCEPTION))  : M (unit)
   | Exception
     {| ExceptionContext_trap := E_SAMO_Addr_Align tt; ExceptionContext_ext := _; ExceptionContext_excinst_offset := _; ExceptionContext_excinst := _; ExceptionContext_excinfo_is_gva := _; ExceptionContext_excinfo2 := _; ExceptionContext_excinfo := _ |} =>
      (generate_event (EV_MISALIGNED_STORE_EXCEPTION))  : M (unit)
   | _ => returnM (tt)
   end
    : M (unit).

