   read_reg pmpcfg_n >>= fun (w__4 : vec (mword 8) 64) =>
   read_reg pmpcfg_n >>= fun (w__5 : vec (mword 8) 64) =>
   read_reg pmpcfg_n >>= fun (w__6 : vec (mword 8) 64) =>
