    else if Z.eqb (l__0) (23) return M (unit) then write_reg vr23 v  : M (unit)
    else if Z.eqb (l__0) (24) return M (unit) then write_reg vr24 v  : M (unit)
    else if Z.eqb (l__0) (25) return M (unit) then write_reg vr25 v  : M (unit)
    else if Z.eqb (l__0) (26) return M (unit) then write_reg vr26 v  : M (unit)
    else if Z.eqb (l__0) (27) return M (unit) then write_reg vr27 v  : M (unit)
    else if Z.eqb (l__0) (28) return M (unit) then write_reg vr28 v  : M (unit)
    else if Z.eqb (l__0) (29) return M (unit) then write_reg vr29 v  : M (unit)
    else if Z.eqb (l__0) (30) return M (unit) then write_reg vr30 v  : M (unit)
    else write_reg vr31 v  : M (unit)) >>
   (dirty_v_context (tt)) >>
   returnM ((vreg_write_callback ((vregno_to_vregidx ((Vregno (r))))) (v))).

Definition rV_bits (i : vregidx) : M (mword (2 ^ 8)) :=
