   write_reg vr14 zero_vreg >>
   write_reg vr15 zero_vreg >>
   write_reg vr16 zero_vreg >>
   write_reg vr17 zero_vreg >>
   write_reg vr18 zero_vreg >>
   write_reg vr19 zero_vreg >>
