Definition _update_Vtype_reserved (v : mword 64) (x : mword (64 - 9)) : mword 64 :=
   update_subrange_vec_dec (v) ((Z.sub (64) (2))) (8) (x).

Definition _update_PTE_Ext_reserved (v : mword 10) (x : mword 5) : mword 10 :=
