Definition set_vstart (value : mword 16) : M (unit) :=
   (dirty_v_context (tt)) >>
   write_reg vstart (zero_extend' (64) ((subrange_vec_dec (value) ((Z.sub (vlen_exp) (1))) (0)))) >>
   ((read_reg vstart)  : M (mword 64)) >>= fun (w__0 : mword 64) =>
   (csr_name_write_callback ("vstart") (w__0))
    : M (unit).

Definition write_vcsr (vxrm_val : mword 2) (vxsat_val : mword 1) : M (unit) :=
   ((read_reg vcsr)  : M (mword 3)) >>= fun (w__0 : mword 3) =>
   write_reg vcsr (update_subrange_vec_dec (w__0) (2) (1) (vxrm_val)) >>
   ((read_reg vcsr)  : M (mword 3)) >>= fun (w__1 : mword 3) =>
