    else if eq_vec (p0_) ((Ox"1")) then returnM ((Ox"00000002"))
    else if eq_vec (p0_) ((Ox"2")) then returnM ((Ox"00000004"))
    else if eq_vec (p0_) ((Ox"3")) then returnM ((Ox"00000008"))
    else if eq_vec (p0_) ((Ox"4")) then returnM ((Ox"00000010"))
    else if eq_vec (p0_) ((Ox"5")) then returnM ((Ox"00000020"))
    else if eq_vec (p0_) ((Ox"6")) then returnM ((Ox"00000040"))
    else if eq_vec (p0_) ((Ox"7")) then returnM ((Ox"00000080"))
    else if eq_vec (p0_) ((Ox"8")) then returnM ((Ox"0000001B"))
    else if eq_vec (p0_) ((Ox"9")) then returnM ((Ox"00000036"))
    else (internal_error ("extensions/K/types_kext.sail") (89) ("Unexpected AES r"))  : M (mword 32))
    : M (mword 32).

