Definition sbox_lookup (x : mword 8) (table : vec (mword 8) 256) : mword 8 :=
   vec_access_dec (table) ((Z.sub (255) ((uint (x))))).

Definition aes_sbox_fwd (x : mword 8) : mword 8 := sbox_lookup (x) (aes_sbox_fwd_table).

Definition aes_sbox_inv (x : mword 8) : mword 8 := sbox_lookup (x) (aes_sbox_inv_table).

Definition aes_subword_fwd (x : mword 32) : mword 32 :=
   concat_vec ((aes_sbox_fwd ((subrange_vec_dec (x) (31) (24)))))
     ((concat_vec ((aes_sbox_fwd ((subrange_vec_dec (x) (23) (16)))))
         ((concat_vec ((aes_sbox_fwd ((subrange_vec_dec (x) (15) (8)))))
             ((aes_sbox_fwd ((subrange_vec_dec (x) (7) (0))))))))).

Definition aes_subword_inv (x : mword 32) : mword 32 :=
   concat_vec ((aes_sbox_inv ((subrange_vec_dec (x) (31) (24)))))
     ((concat_vec ((aes_sbox_inv ((subrange_vec_dec (x) (23) (16)))))
         ((concat_vec ((aes_sbox_inv ((subrange_vec_dec (x) (15) (8)))))
             ((aes_sbox_inv ((subrange_vec_dec (x) (7) (0))))))))).

Definition sm4_sbox (x : mword 8) : mword 8 := sbox_lookup (x) (sm4_sbox_table).

Definition aes_get_column (state : mword 128) (c : Z) (*(0 <=? c) && (c <=? 3)*) : mword 32 :=
   autocast (T := mword)
   (subrange_vec_dec (state) ((Z.add ((Z.mul (32) (c))) (31))) ((Z.mul (32) (c)))).

