   concat_vec ((aes_sbox_fwd ((subrange_vec_dec (x) (63) (56)))))
     ((concat_vec ((aes_sbox_fwd ((subrange_vec_dec (x) (55) (48)))))
         ((concat_vec ((aes_sbox_fwd ((subrange_vec_dec (x) (47) (40)))))
             ((concat_vec ((aes_sbox_fwd ((subrange_vec_dec (x) (39) (32)))))
                 ((concat_vec ((aes_sbox_fwd ((subrange_vec_dec (x) (31) (24)))))
                     ((concat_vec ((aes_sbox_fwd ((subrange_vec_dec (x) (23) (16)))))
                         ((concat_vec ((aes_sbox_fwd ((subrange_vec_dec (x) (15) (8)))))
                             ((aes_sbox_fwd ((subrange_vec_dec (x) (7) (0))))))))))))))))).

Definition aes_apply_inv_sbox_to_each_byte (x : mword 64) : mword 64 :=
   concat_vec ((aes_sbox_inv ((subrange_vec_dec (x) (63) (56)))))
