Definition aes_shift_rows_fwd (x : mword 128) : mword 128 :=
   let ic3 : bits 32 := aes_get_column (x) (3) in
   let ic2 : bits 32 := aes_get_column (x) (2) in
   let ic1 : bits 32 := aes_get_column (x) (1) in
   let ic0 : bits 32 := aes_get_column (x) (0) in
   let oc0 : bits 32 :=
     concat_vec ((subrange_vec_dec (ic3) (31) (24)))
       ((concat_vec ((subrange_vec_dec (ic2) (23) (16)))
           ((concat_vec ((subrange_vec_dec (ic1) (15) (8))) ((subrange_vec_dec (ic0) (7) (0))))))) in
   let oc1 : bits 32 :=
     concat_vec ((subrange_vec_dec (ic0) (31) (24)))
       ((concat_vec ((subrange_vec_dec (ic3) (23) (16)))
           ((concat_vec ((subrange_vec_dec (ic2) (15) (8))) ((subrange_vec_dec (ic1) (7) (0))))))) in
   let oc2 : bits 32 :=
     concat_vec ((subrange_vec_dec (ic1) (31) (24)))
       ((concat_vec ((subrange_vec_dec (ic0) (23) (16)))
           ((concat_vec ((subrange_vec_dec (ic3) (15) (8))) ((subrange_vec_dec (ic2) (7) (0))))))) in
   let oc3 : bits 32 :=
     concat_vec ((subrange_vec_dec (ic2) (31) (24)))
       ((concat_vec ((subrange_vec_dec (ic1) (23) (16)))
           ((concat_vec ((subrange_vec_dec (ic0) (15) (8))) ((subrange_vec_dec (ic3) (7) (0))))))) in
   concat_vec (oc3) ((concat_vec (oc2) ((concat_vec (oc1) (oc0))))).

