     let typ := trig_type_bits_forwards (tt') in
     orb ((generic_eq (typ) (TT_none)))
       ((orb ((generic_eq (typ) (TT_disabled)))
           ((orb ((andb ((generic_eq (typ) (TT_icount))) (sdtrig_has_icount)))
               ((orb ((andb ((generic_eq (typ) (TT_etrigger))) (sdtrig_has_etrigger)))
                   ((andb ((generic_eq (typ) (TT_itrigger))) (sdtrig_has_itrigger))))))))).

