   let info : bits 16 := shiftl (flag) ((uint (w__0))) in
   (if sdtrig_has_icount return M (mword 16) then
      (trig_type_bits_backwards (TT_icount)) >>= fun (w__1 : mword 4) =>
      let info := (or_vec (info) ((shiftl (flag) ((uint (w__1))))))  : mword 16 in
      returnM (info)
    else returnM (info)) >>= fun (info : mword 16) =>
   (if sdtrig_has_etrigger return M (mword 16) then
      (trig_type_bits_backwards (TT_etrigger)) >>= fun (w__2 : mword 4) =>
      let info := (or_vec (info) ((shiftl (flag) ((uint (w__2))))))  : mword 16 in
      returnM (info)
    else returnM (info)) >>= fun (info : mword 16) =>
   (if sdtrig_has_itrigger return M (mword 16) then
      (trig_type_bits_backwards (TT_itrigger)) >>= fun (w__3 : mword 4) =>
      let info := (or_vec (info) ((shiftl (flag) ((uint (w__3))))))  : mword 16 in
      returnM (info)
    else returnM (info))
    : M (mword 16).

