Definition MControl6_to_bits (t : MControl6) : M (mword 64) :=
   let hit := hit_bits_backwards (t.(MControl6_hit)) in
   (trig_type_bits_backwards (TT_mcontrol6)) >>= fun (w__0 : mword 4) =>
   returnM ((_update_MControl6_bits_load
               ((_update_MControl6_bits_store
                   ((_update_MControl6_bits_execute
                       ((_update_MControl6_bits_u
                           ((_update_MControl6_bits_s
                               ((_update_MControl6_bits_uncertainen
                                   ((_update_MControl6_bits_m
                                       ((_update_MControl6_bits_t_match
                                           ((_update_MControl6_bits_chain
                                               ((_update_MControl6_bits_action
                                                   ((_update_MControl6_bits_size
                                                       ((_update_MControl6_bits_select
                                                           ((_update_MControl6_bits_hit0
                                                               ((_update_MControl6_bits_vu
                                                                   ((_update_MControl6_bits_vs
                                                                       ((_update_MControl6_bits_hit1
                                                                           ((_update_MControl6_bits_uncertain
                                                                               ((_update_MControl6_bits_dmode
                                                                                   ((_update_MControl6_bits_trig_type
                                                                                       ((Mk_MControl6_bits
                                                                                           ((zeros'
                                                                                               (64)))))
                                                                                       (w__0)))
                                                                                   ((bool_bit_forwards
                                                                                       (t.(MControl6_dmode))))))
                                                                               ((bool_bit_forwards
                                                                                   (t.(MControl6_uncertain))))))
                                                                           ((vec_of_bits [access_vec_dec
                                                                                            (hit)
                                                                                            (1)]
                                                                              : mword 1))))
                                                                       ((bool_bit_forwards
                                                                           (t.(MControl6_vs))))))
                                                                   ((bool_bit_forwards
                                                                       (t.(MControl6_vu))))))
                                                               ((vec_of_bits [access_vec_dec (hit)
                                                                                (0)]
                                                                  : mword 1))))
                                                           ((compare_select_bits_backwards
                                                               (t.(MControl6_select))))))
                                                       ((trig_match_size_backwards
                                                           (t.(MControl6_size))))))
                                                   ((subrange_vec_dec
                                                       ((trig_action_backwards
                                                           (t.(MControl6_action)))) (3) (0)))))
                                               ((bool_bit_forwards (t.(MControl6_chain))))))
                                           ((trig_match_val_backwards (t.(MControl6_t_match))))))
                                       ((bool_bit_forwards (t.(MControl6_m))))))
                                   ((bool_bit_forwards (t.(MControl6_uncertainen))))))
                               ((bool_bit_forwards (t.(MControl6_s))))))
                           ((bool_bit_forwards (t.(MControl6_u))))))
                       ((bool_bit_forwards (t.(MControl6_execute))))))
                   ((bool_bit_forwards (t.(MControl6_store))))))
               ((bool_bit_forwards (t.(MControl6_load)))))).

