Definition update_triggers '(tt : unit) : M (unit) :=
   read_reg written_trigger_index >>= fun (w__0 : option ((Z * tdata))) =>
   match w__0 with
   | None => returnM (tt)
   | Some (idx, TDATA1) =>
      read_reg triggers >>= fun (w__1 : vec Trigger 16) =>
      match vec_access_dec (w__1) (idx) with
      | T_icount t =>
         match t.(ICount_new_count) with
         | Some c =>
            read_reg triggers >>= fun (w__2 : vec Trigger 16) =>
            write_reg
              triggers
              (vec_update_dec (w__2) (idx)
                 ((T_icount
                     ({| ICount_dmode := t.(ICount_dmode);
                         ICount_vs := t.(ICount_vs);
                         ICount_vu := t.(ICount_vu);
                         ICount_hit := t.(ICount_hit);
                         ICount_count := c;
                         ICount_m := t.(ICount_m);
                         ICount_pending := t.(ICount_pending);
                         ICount_s := t.(ICount_s);
                         ICount_u := t.(ICount_u);
                         ICount_new_count := None;
                         ICount_action := t.(ICount_action);
                         ICount_active := true;
                         ICount_tdata2 := t.(ICount_tdata2);
                         ICount_tdata3 := t.(ICount_tdata3) |}))))
             : M (unit)
         | None =>
            (assert_exp t.(ICount_active) "extensions/Sdtrig/sdtrig_control.sail:250.36-250.37")
             : M (unit)
         end
          : M (unit)
      | _ => returnM (tt)
      end >>
      write_reg written_trigger_index None
       : M (unit)
   | Some _ => write_reg written_trigger_index None  : M (unit)
   end
    : M (unit).

