Definition undefined_AtomicSupport '(tt : unit) : M (AtomicSupport) :=
   (internal_pick ([AMONone; AMOSwap; AMOLogical; AMOArithmetic; AMOCASW; AMOCASD; AMOCASQ]))
    : M (AtomicSupport).

Definition atomic_support_str_forwards_matches (arg_ : AtomicSupport) : bool :=
   match arg_ with
   | AMONone => true
   | AMOSwap => true
   | AMOLogical => true
   | AMOArithmetic => true
   | AMOCASW => true
   | AMOCASD => true
   | AMOCASQ => true
