Definition atomic_support_str_backwards_matches (arg_ : string) : bool :=
   let p0_ := arg_ in
   if generic_eq (p0_) ("AMONone") then true
   else if generic_eq (p0_) ("AMOSwap") then true
   else if generic_eq (p0_) ("AMOLogical") then true
   else if generic_eq (p0_) ("AMOArithmetic") then true
   else if generic_eq (p0_) ("AMOCASW") then true
   else if generic_eq (p0_) ("AMOCASD") then true
   else if generic_eq (p0_) ("AMOCASQ") then true
   else false.

Definition pma_allows_atomic_op (pma : AtomicSupport) (op : amoop) (width : Z)
(*(0 <? width) && (width <=? 4096)*)
: bool :=
   match pma with
   | AMONone => false
   | AMOSwap => generic_eq (op) (AMOSWAP)
   | AMOLogical =>
      orb ((generic_eq (op) (AMOSWAP)))
        ((orb ((generic_eq (op) (AMOAND)))
            ((orb ((generic_eq (op) (AMOOR))) ((generic_eq (op) (AMOXOR)))))))
   | AMOArithmetic => generic_neq (op) (AMOCAS)
   | AMOCASW => orb ((generic_neq (op) (AMOCAS))) ((Z.leb (width) (4)))
   | AMOCASD => orb ((generic_neq (op) (AMOCAS))) ((Z.leb (width) (8)))
   | AMOCASQ => orb ((generic_neq (op) (AMOCAS))) ((Z.leb (width) (16)))
   end.

