Definition check_PTE_permission
(access : MemoryAccessType mem_payload) (priv : Privilege) (stage : TranslationStage) (mxr : bool)
(do_sum : bool) (pte_flags : mword 8) (_ext : mword 10) (_ext_ptw : unit)
: M (PTE_Check) :=
   catch_early_return
     (let pte_U := bit_to_bool ((_get_PTE_Flags_U (pte_flags))) in
     let pte_R := bit_to_bool ((_get_PTE_Flags_R (pte_flags))) in
     let pte_W := bit_to_bool ((_get_PTE_Flags_W (pte_flags))) in
     let pte_X := bit_to_bool ((_get_PTE_Flags_X (pte_flags))) in
     liftR (assert_exp (zopz0zJzJzK (pte_W) ((orb (pte_R) ((not (pte_X)))))) "sys/vmem_pte.sail:160.39-160.40") >>
     match priv with
     | User => returnR (PTE_Check) (pte_U)
     | Supervisor =>
        returnR (PTE_Check) ((orb ((not (pte_U))) ((andb (do_sum) ((is_load_store (access)))))))
     | Machine =>
        liftR ((internal_error ("sys/vmem_pte.sail") (168) ("m-mode mem perm check")))
         : MR (PTE_Check) (bool)
     | VirtualUser => returnR (PTE_Check) (pte_U)
     | VirtualSupervisor =>
        returnR (PTE_Check) ((orb ((not (pte_U))) ((andb (do_sum) ((is_load_store (access)))))))
     end >>= fun (priv_ok : bool) =>
     (if not (priv_ok) then returnR (PTE_Check) ((PTE_Check_Failure ((tt, PTE_No_Permission (tt)))))
      else
        (if generic_eq (stage) (G_Stage) return MR (PTE_Check) (unit) then
           (and_boolM (liftR ((is_shadow_stack_access (access)))  : MR (PTE_Check) (bool))
              (returnR (PTE_Check) ((not ((andb (pte_R) (pte_W))))))) >>= fun w__2 =>
           (if w__2 return MR (PTE_Check) (unit) then
              (early_return ((PTE_Check_Failure ((tt, PTE_No_Permission (tt))))
               : PTE_Check) :
                MR PTE_Check unit)
               : MR (PTE_Check) (unit)
            else returnR (PTE_Check) (tt))
            : MR (PTE_Check) (unit)
         else if andb ((not (pte_R))) ((andb (pte_W) ((not (pte_X)))))
           return
           MR (PTE_Check) (unit) then
           ((liftR (read_reg menvcfg))  : MR (PTE_Check) (mword 64)) >>= fun (w__3 : mword 64) =>
           liftR (assert_exp (bool_bit_backwards ((_get_MEnvcfg_SSE (w__3)))) "sys/vmem_pte.sail:186.33-186.34") >>
           match access with
           | InstructionFetch tt => returnR (PTE_Check) (false)
           | Load PageTableEntry => returnR (PTE_Check) (false)
           | Store PageTableEntry => returnR (PTE_Check) (false)
           | Load Data => returnR (PTE_Check) (true)
           | Load Vector => returnR (PTE_Check) (true)
           | Load ShadowStack => returnR (PTE_Check) (true)
           | LoadExecute Data => returnR (PTE_Check) (true)
           | LoadReserved (_, _, Data) => returnR (PTE_Check) (true)
           | Store Data => returnR (PTE_Check) (false)
           | Store Vector => returnR (PTE_Check) (false)
           | StoreConditional (_, _, Data) => returnR (PTE_Check) (false)
           | Atomic (_, _, _, Data, Data) => returnR (PTE_Check) (false)
           | Store ShadowStack => returnR (PTE_Check) (true)
           | Atomic (_, _, _, ShadowStack, ShadowStack) => returnR (PTE_Check) (true)
           | CacheAccess _ => returnR (PTE_Check) (false)
           | LoadExecute p =>
              liftR ((internal_error ("sys/vmem_pte.sail") (216)
                        ((String.append ("Invalid payload (")
                            ((String.append ((mem_payload_name_forwards (p))) (") for LoadExecute.")))))))
               : MR (PTE_Check) (bool)
           | LoadReserved (_, _, p) =>
              liftR ((internal_error ("sys/vmem_pte.sail") (217)
                        ((String.append ("Invalid payload (")
                            ((String.append ((mem_payload_name_forwards (p)))
                                (") for LoadReserved.")))))))
               : MR (PTE_Check) (bool)
           | StoreConditional (_, _, p) =>
              liftR ((internal_error ("sys/vmem_pte.sail") (218)
                        ((String.append ("Invalid payload (")
                            ((String.append ((mem_payload_name_forwards (p)))
                                (") for StoreConditional.")))))))
               : MR (PTE_Check) (bool)
           | Atomic (_, _, _, rp, wp) =>
              liftR ((internal_error ("sys/vmem_pte.sail") (219)
                        ((String.append ("Invalid payloads (")
                            ((String.append ((mem_payload_name_forwards (rp)))
                                ((String.append (", ")
                                    ((String.append ((mem_payload_name_forwards (wp)))
                                        (") for Atomic.")))))))))))
               : MR (PTE_Check) (bool)
           end >>= fun (shadow_stack_ok : bool) =>
           (early_return ((if not (shadow_stack_ok) then
                             PTE_Check_Failure ((tt, PTE_No_Access (tt)))
                           else PTE_Check_Success (tt))
            : PTE_Check) :
             MR PTE_Check unit)
            : MR (PTE_Check) (unit)
         else
         liftR ((is_shadow_stack_access (access))) >>= fun (w__8 : bool) =>
         if w__8 return MR (PTE_Check) (unit) then
           let is_read_only := andb (pte_R) ((andb ((not (pte_W))) ((not (pte_X))))) in
           (early_return ((PTE_Check_Failure
                             ((tt, if is_read_only then PTE_No_Permission (tt)
                             else PTE_No_Access (tt))))
            : PTE_Check) :
             MR PTE_Check unit)
            : MR (PTE_Check) (unit)
         else returnR (PTE_Check) (tt)) >>
        let pte_R := orb (pte_R) ((andb (pte_X) (mxr))) in
        let access_ok : bool :=
          match access with
          | Load _ => pte_R
          | LoadReserved _ => pte_R
          | Store _ => pte_W
          | StoreConditional _ => pte_W
          | Atomic _ => andb (pte_W) (pte_R)
          | InstructionFetch _ => pte_X
          | LoadExecute _ => pte_X
          | CacheAccess (CB_zero tt) => pte_W
          | CacheAccess (CB_prefetch p) =>
             match p with | PREFETCH_R => pte_R | PREFETCH_W => pte_W | PREFETCH_I => pte_X end
          | CacheAccess (CB_manage _) => orb (pte_R) (pte_W)
