        returnR (PTE_Check) ((if not (access_ok) then
                                PTE_Check_Failure ((tt, PTE_No_Permission (tt)))
                              else PTE_Check_Success (tt))))
      : MR (PTE_Check) (PTE_Check)).

Definition update_PTE_Bits {pte_size : Z}
(pte : mword pte_size) (access : MemoryAccessType mem_payload) (*pte_size >=? 0*)
(*member_Z_list pte_size [32; 64]*)
: option (mword pte_size) :=
   let pte_flags := Mk_PTE_Flags ((subrange_vec_dec (pte) (7) (0))) in
   let update_d : bool :=
     andb ((eq_vec ((_get_PTE_Flags_D (pte_flags))) (('b"0"))))
       ((match access with
       | InstructionFetch tt => false
       | LoadExecute _ => false
       | Load _ => false
       | LoadReserved _ => false
       | Store _ => true
       | StoreConditional _ => true
       | Atomic _ => true
       | CacheAccess (CB_manage _) => false
       | CacheAccess (CB_zero tt) => true
       | CacheAccess (CB_prefetch _) => false
       end
        : bool)) in
   let update_a :=
     andb ((eq_vec ((_get_PTE_Flags_A (pte_flags))) (('b"0"))))
       ((not ((is_prefetch_access (access))))) in
   if orb (update_d) (update_a) then
     let pte_flags :=
       _update_PTE_Flags_D ((_update_PTE_Flags_A (pte_flags) (('b"1"))))
         ((if update_d then ('b"1")
           else _get_PTE_Flags_D (pte_flags))) in
     Some ((update_subrange_vec_dec (pte) (7) (0) (pte_flags)))
   else None.

