   | (CacheAccess (CB_zero tt), _) => returnM ((E_SAMO_Page_Fault (tt)))
   | (CacheAccess (CB_prefetch p), PTW_No_Access tt) =>
      returnM (match p with
      | PREFETCH_R => E_Load_Access_Fault (tt)
      | PREFETCH_W => E_SAMO_Access_Fault (tt)
