Definition match_TLB_Entry
(ent : TLB_Entry) (asid : mword ((if 64 =? 32 then 9 else 16)))
(vmid : mword ((if 64 =? 32 then 7 else 14))) (vpn : mword (59 - 12)) (stage : TranslationStage)
: bool :=
   let asid_matches := orb (ent.(TLB_Entry_global)) ((eq_vec (ent.(TLB_Entry_asid)) (asid))) in
   let vmid_matches := eq_vec (ent.(TLB_Entry_vmid)) (vmid) in
   let vpn_matches :=
     eq_vec (ent.(TLB_Entry_vpn)) ((and_vec (vpn) ((not_vec (ent.(TLB_Entry_levelMask)))))) in
   let stage_matches := generic_eq (ent.(TLB_Entry_stage)) (stage) in
   match stage with
   | S_Stage => andb (asid_matches) ((andb (vpn_matches) (stage_matches)))
   | VS_Stage => andb (asid_matches) ((andb (vmid_matches) ((andb (vpn_matches) (stage_matches)))))
   | G_Stage => andb (vmid_matches) ((andb (vpn_matches) (stage_matches)))
   end.

Definition flush_TLB_Entry
(ent : TLB_Entry) (asid : option (mword ((if 64 =? 32 then 9 else 16))))
(vmid : option (mword ((if 64 =? 32 then 7 else 14)))) (vaddr : option (mword 64))
(stage : TranslationStage)
: bool :=
   let asid_matches : bool :=
     match asid with
     | Some asid => andb ((eq_vec (ent.(TLB_Entry_asid)) (asid))) ((not (ent.(TLB_Entry_global))))
     | None => true
     end in
   let vmid_matches : bool :=
     match vmid with | Some vmid => eq_vec (ent.(TLB_Entry_vmid)) (vmid) | None => true end in
   let addr_matches : bool :=
     match vaddr with
     | Some vaddr =>
        let vaddr : bits 64 :=
          match stage with
          | G_Stage => shiftl ((zero_extend' (64) (vaddr))) (2)
          | _ => sign_extend' (64) (vaddr)
          end in
        eq_vec (ent.(TLB_Entry_vpn))
          ((and_vec ((subrange_vec_dec (vaddr) (58) (pagesize_bits)))
              ((not_vec (ent.(TLB_Entry_levelMask))))))
     | None => true
     end in
   let stage_matches := generic_eq (ent.(TLB_Entry_stage)) (stage) in
   andb (asid_matches) ((andb (vmid_matches) ((andb (addr_matches) (stage_matches))))).

Definition lookup_TLB
(sv_width : Z) (asid : mword ((if 64 =? 32 then 9 else 16)))
(vmid : mword ((if 64 =? 32 then 7 else 14))) (vpn : mword (sv_width - 12))
(stage : TranslationStage)
(*member_Z_list sv_width [32; 39; 48; 57] || member_Z_list sv_width [34; 41; 50; 59]*)
: M (option ((Z * TLB_Entry))) :=
   let index := tlb_hash ((__id (sv_width))) (vpn) (stage) in
   read_reg tlb >>= fun (w__0 : vec (option TLB_Entry) (2 ^ 6)) =>
   let w__1 : option ((Z * TLB_Entry)) :=
     match vec_access_dec (w__0) (index) with
     | None => None
     | Some entry =>
        let vpn : bits tlb_vpn_bits :=
          if generic_eq (stage) (G_Stage) then zero_extend' ((Z.sub (59) (12))) (vpn)
          else sign_extend' ((Z.sub (59) (12))) (vpn) in
        if match_TLB_Entry (entry) (asid) (vmid) (vpn) (stage) then Some ((index, entry))
        else None
     end in
   returnM (w__1).

Definition add_to_TLB
(sv_width : Z) (asid : mword ((if 64 =? 32 then 9 else 16)))
(vmid : mword ((if 64 =? 32 then 7 else 14))) (vpn : mword (sv_width - 12))
(ppn : mword ((if (sv_width =? 32) || (sv_width =? 34) then 22 else 44)))
(pte : mword ((if (sv_width =? 32) || (sv_width =? 34) then 32 else 64))) (pteAddr : physaddr)
(level : Z) (global : bool) (stage : TranslationStage)
(*member_Z_list sv_width [32; 39; 48; 57] || member_Z_list sv_width [34; 41; 50; 59]*)
