   (and_boolM ((currentlyEnabled (Ext_Smdbltrp))  : M (bool))
      (returnM (((generic_eq (prev_priv) (Machine))  : bool)))) >>= fun (w__1 : bool) =>
   (if w__1 return M (unit) then
      ((read_reg mstatus)  : M (mword 64)) >>= fun (w__2 : mword 64) =>
