      (returnM ((match prev_priv with
       | Machine =>
          orb ((generic_eq (new_priv) (User)))
            ((orb ((generic_eq (new_priv) (VirtualSupervisor)))
                ((generic_eq (new_priv) (VirtualUser)))))
       | Supervisor => true
       | _ => false
