      ((and_boolM
          ((read_henvcfg (tt)) >>= fun (w__7 : mword 64) =>
           returnM (((eq_vec ((_get_HEnvcfg_DTE (w__7))) (('b"1")))  : bool)))
          (returnM (((orb ((generic_eq (new_priv) (VirtualUser)))
                        ((generic_eq (prev_priv) (VirtualSupervisor))))
            : bool))))
       : M (bool))) >>= fun (w__9 : bool) =>
   (if w__9 return M (unit) then
      ((read_reg vsstatus)  : M (mword 64)) >>= fun (w__10 : mword 64) =>
