Definition feq_quiet_S (v1 : mword 32) (v2 : mword 32) : (bool * mword 5) :=
   let '((s1, e1, m1)) := fsplit_S (v1) in
   let '((s2, e2, m2)) := fsplit_S (v2) in
   let v1Is0 := orb ((f_is_neg_zero_S (v1))) ((f_is_pos_zero_S (v1))) in
   let v2Is0 := orb ((f_is_neg_zero_S (v2))) ((f_is_pos_zero_S (v2))) in
   let result' := orb ((eq_vec (v1) (v2))) ((andb (v1Is0) (v2Is0))) in
   let fflags := if orb ((f_is_SNaN_S (v1))) ((f_is_SNaN_S (v2))) then nvFlag (tt) else zeros' (5) in
   ((result', fflags)).

Definition flt_S (v1 : mword 32) (v2 : mword 32) (is_quiet : bool) : (bool * mword 5) :=
   let '((s1, e1, m1)) := fsplit_S (v1) in
   let '((s2, e2, m2)) := fsplit_S (v2) in
   let result' : bool :=
     if andb ((eq_vec (s1) (('b"0")))) ((eq_vec (s2) (('b"0")))) then
       if eq_vec (e1) (e2) then Z.ltb ((uint (m1))) ((uint (m2)))
       else Z.ltb ((uint (e1))) ((uint (e2)))
     else if andb ((eq_vec (s1) (('b"0")))) ((eq_vec (s2) (('b"1")))) then false
     else if andb ((eq_vec (s1) (('b"1")))) ((eq_vec (s2) (('b"0")))) then true
     else if eq_vec (e1) (e2) then Z.gtb ((uint (m1))) ((uint (m2)))
     else Z.gtb ((uint (e1))) ((uint (e2))) in
   let fflags :=
     if is_quiet then
       if orb ((f_is_SNaN_S (v1))) ((f_is_SNaN_S (v2))) then nvFlag (tt)
       else zeros' (5)
     else if orb ((f_is_NaN_S (v1))) ((f_is_NaN_S (v2))) then nvFlag (tt)
     else zeros' (5) in
   ((result', fflags)).

Definition fle_S (v1 : mword 32) (v2 : mword 32) (is_quiet : bool) : (bool * mword 5) :=
   let '((s1, e1, m1)) := fsplit_S (v1) in
   let '((s2, e2, m2)) := fsplit_S (v2) in
   let v1Is0 := orb ((f_is_neg_zero_S (v1))) ((f_is_pos_zero_S (v1))) in
   let v2Is0 := orb ((f_is_neg_zero_S (v2))) ((f_is_pos_zero_S (v2))) in
   let result' : bool :=
     if andb ((eq_vec (s1) (('b"0")))) ((eq_vec (s2) (('b"0")))) then
       if eq_vec (e1) (e2) then Z.leb ((uint (m1))) ((uint (m2)))
       else Z.ltb ((uint (e1))) ((uint (e2)))
     else if andb ((eq_vec (s1) (('b"0")))) ((eq_vec (s2) (('b"1")))) then andb (v1Is0) (v2Is0)
     else if andb ((eq_vec (s1) (('b"1")))) ((eq_vec (s2) (('b"0")))) then true
     else if eq_vec (e1) (e2) then Z.geb ((uint (m1))) ((uint (m2)))
     else Z.gtb ((uint (e1))) ((uint (e2))) in
   let fflags :=
     if is_quiet then
       if orb ((f_is_SNaN_S (v1))) ((f_is_SNaN_S (v2))) then nvFlag (tt)
       else zeros' (5)
     else if orb ((f_is_NaN_S (v1))) ((f_is_NaN_S (v2))) then nvFlag (tt)
     else zeros' (5) in
   ((result', fflags)).

