Definition fsplit_H (xf16 : mword 16) : (mword 1 * mword 5 * mword 10) :=
   ((subrange_vec_dec (xf16) (15) (15), subrange_vec_dec (xf16) (14) (10), subrange_vec_dec (xf16)
                                                                             (9) (0))).

Definition fmake_H (sign : mword 1) (exp : mword 5) (mant : mword 10) : mword 16 :=
   concat_vec (sign) ((concat_vec (exp) (mant))).

Definition negate_H (xf16 : mword 16) : mword 16 :=
   let '((sign, exp, mant)) := fsplit_H (xf16) in
   let new_sign := if eq_vec (sign) (('b"0")) then ('b"1") else ('b"0") in
   fmake_H (new_sign) (exp) (mant).

Definition f_is_neg_inf_H (xf16 : mword 16) : bool :=
