Definition fle_H (v1 : mword 16) (v2 : mword 16) (is_quiet : bool) : (bool * mword 5) :=
   let '((s1, e1, m1)) := fsplit_H (v1) in
   let '((s2, e2, m2)) := fsplit_H (v2) in
