Definition fcvtmod_helper (x64 : mword 64) : (mword 5 * mword 32) :=
   let '((sign, exp, mant)) := fsplit_D (x64) in
   let is_subnorm := andb ((eq_vec (exp) ((zeros' (11))))) ((neq_vec (mant) ((zeros' (52))))) in
   let is_zero := andb ((eq_vec (exp) ((zeros' (11))))) ((eq_vec (mant) ((zeros' (52))))) in
   let is_nan_or_inf := eq_vec (exp) ((ones (11))) in
   let true_mant := concat_vec (('b"1")) (mant) in
   let true_exp := Z.sub ((uint (exp))) (1023) in
   let is_too_large := Z.geb (true_exp) (84) in
   let is_too_small := Z.ltb (true_exp) (0) in
   if is_zero then ((zeros' (5), zeros' (32)))
   else if is_subnorm then ((nxFlag (tt), zeros' (32)))
   else if is_nan_or_inf then ((nvFlag (tt), zeros' (32)))
   else if is_too_large then ((nvFlag (tt), zeros' (32)))
   else if is_too_small then ((nxFlag (tt), zeros' (32)))
   else
     let fixedpoint : bits 84 := shiftl ((zero_extend' (84) (true_mant))) (true_exp) in
     let integer := subrange_vec_dec (fixedpoint) (83) (52) in
     let fractional := subrange_vec_dec (fixedpoint) (51) (0) in
     let result' :=
       if eq_vec (sign) (('b"1")) then add_vec_int ((not_vec (integer))) (1)
       else integer in
     let max_integer :=
       if eq_vec (sign) (('b"1")) then uint ((Ox"80000000"))
       else uint ((Ox"7FFFFFFF")) in
     let flags : bits 5 :=
       if Z.gtb (true_exp) (31) then nvFlag (tt)
       else if Z.gtb ((uint (integer))) (max_integer) then nvFlag (tt)
       else if neq_vec (fractional) ((zeros' ((Z.add ((Z.sub (51) (0))) (1))))) then nxFlag (tt)
       else zeros' (5) in
     ((flags, result')).

