Definition undefined_seed_opst '(tt : unit) : M (seed_opst) :=
   (internal_pick ([BIST; ES16; WAIT; DEAD]))  : M (seed_opst).

Definition opst_code_forwards (arg_ : seed_opst) : mword 2 :=
   match arg_ with | BIST => ('b"00") | WAIT => ('b"01") | ES16 => ('b"10") | DEAD => ('b"11") end.

Definition opst_code_backwards (arg_ : mword 2) : seed_opst :=
   let p0_ := arg_ in
   if eq_vec (p0_) (('b"00")) then BIST
   else if eq_vec (p0_) (('b"01")) then WAIT
   else if eq_vec (p0_) (('b"10")) then ES16
   else DEAD.

Definition opst_code_forwards_matches (arg_ : seed_opst) : bool :=
   match arg_ with | BIST => true | WAIT => true | ES16 => true | DEAD => true end.

Definition opst_code_backwards_matches (arg_ : mword 2) : bool :=
   let p0_ := arg_ in
   if eq_vec (p0_) (('b"00")) then true
   else if eq_vec (p0_) (('b"01")) then true
   else if eq_vec (p0_) (('b"10")) then true
   else if eq_vec (p0_) (('b"11")) then true
   else false.

Definition read_seed_csr '(tt : unit) : M (mword 64) :=
   let reserved_bits : bits 6 := ('b"000000") in
   let custom_bits : bits 8 := (Ox"00") in
   (get_16_random_bits (tt)) >>= fun (seed : bits 16) =>
   returnM ((zero_extend' (64)
               ((concat_vec ((opst_code_forwards (ES16)))
                   ((concat_vec (reserved_bits) ((concat_vec (custom_bits) (seed))))))))).

Definition write_seed_csr '(tt : unit) : mword 64 := zeros' (64).

