      ((read_reg hstatus)  : M (mword 64)) >>= fun (w__6 : mword 64) =>
      returnM ((eq_vec ((_get_Hstatus_VTSR (w__6))) (('b"1"))))
   | _ => returnM (false)
   end >>= fun (sret_virtual : bool) =>
   (if sret_illegal then returnM ((Illegal_Instruction (tt)))
    else if sret_virtual then returnM ((Virtual_Instruction (tt)))
    else if not ((ext_check_xret_priv (Supervisor))) then returnM ((Ext_XRET_Priv_Failure (tt)))
    else
      read_reg cur_privilege >>= fun prev_priv =>
      (inVirtualPrivilege (tt)) >>= fun (w__7 : bool) =>
      (if w__7 return M (Privilege) then
         ((read_reg vsstatus)  : M (mword 64)) >>= fun (w__8 : mword 64) =>
         let new_priv :=
           if eq_vec ((_get_Mstatus_SPP (w__8))) (('b"1")) then VirtualSupervisor
           else VirtualUser in
         ((read_reg vsstatus)  : M (mword 64)) >>= fun (w__9 : mword 64) =>
         write_reg vsstatus (update_subrange_vec_dec (w__9) (8) (8) (('b"0"))) >>
         ((read_reg vsstatus)  : M (mword 64)) >>= fun (w__10 : mword 64) =>
         ((read_reg vsstatus)  : M (mword 64)) >>= fun (w__11 : mword 64) =>
         write_reg vsstatus (update_subrange_vec_dec (w__10) (1) (1) ((_get_Mstatus_SPIE (w__11)))) >>
         ((read_reg vsstatus)  : M (mword 64)) >>= fun (w__12 : mword 64) =>
         write_reg vsstatus (update_subrange_vec_dec (w__12) (5) (5) (('b"1"))) >>
