       else
         ((read_reg mstatus)  : M (mword 64)) >>= fun (w__13 : mword 64) =>
         ((read_reg hstatus)  : M (mword 64)) >>= fun (w__14 : mword 64) =>
         (currentlyEnabled (Ext_H)) >>= fun (w__15 : bool) =>
         (privLevel_bits_forwards
            ((concat_vec (('b"0")) ((_get_Mstatus_SPP (w__13))), and_vec
                                                                   ((_get_Hstatus_SPV (w__14)))
                                                                   ((bool_to_bit (w__15)))))) >>= fun new_priv =>
         ((read_reg hstatus)  : M (mword 64)) >>= fun (w__16 : mword 64) =>
         write_reg hstatus (update_subrange_vec_dec (w__16) (7) (7) (('b"0"))) >>
         ((read_reg mstatus)  : M (mword 64)) >>= fun (w__17 : mword 64) =>
