         write_reg mstatus (update_subrange_vec_dec (w__18) (1) (1) ((_get_Mstatus_SPIE (w__19)))) >>
         ((read_reg mstatus)  : M (mword 64)) >>= fun (w__20 : mword 64) =>
         write_reg mstatus (update_subrange_vec_dec (w__20) (5) (5) (('b"1"))) >>
         (if generic_neq (new_priv) (Machine) return M (unit) then
            ((read_reg mstatus)  : M (mword 64)) >>= fun (w__21 : mword 64) =>
            write_reg mstatus (update_subrange_vec_dec (w__21) (17) (17) (('b"0")))
             : M (unit)
