Definition execute_FENCE
(_fm : mword 4) (pred : mword 4) (succ : mword 4) (_rs : regidx) (_rd : regidx)
: M (ExecutionResult) :=
   (is_fiom_active (tt)) >>= fun fiom =>
   let pred := effective_fence_set (pred) (fiom) in
   let succ := effective_fence_set (succ) (fiom) in
   match (subrange_vec_dec (pred) (1) (0), subrange_vec_dec (succ) (1) (0)) with
   | (p0_, p1_) =>
      (if andb ((eq_vec (p1_) (('b"11")))) ((eq_vec (p0_) (('b"11")))) return M (unit) then
         (sail_barrier (Barrier_RISCV_rw_rw))
          : M (unit)
       else if andb ((eq_vec (p1_) (('b"11")))) ((eq_vec (p0_) (('b"10")))) return M (unit) then
         (sail_barrier (Barrier_RISCV_r_rw))
          : M (unit)
       else if andb ((eq_vec (p1_) (('b"10")))) ((eq_vec (p0_) (('b"10")))) return M (unit) then
         (sail_barrier (Barrier_RISCV_r_r))
          : M (unit)
       else if andb ((eq_vec (p1_) (('b"01")))) ((eq_vec (p0_) (('b"11")))) return M (unit) then
         (sail_barrier (Barrier_RISCV_rw_w))
          : M (unit)
       else if andb ((eq_vec (p1_) (('b"01")))) ((eq_vec (p0_) (('b"01")))) return M (unit) then
         (sail_barrier (Barrier_RISCV_w_w))
          : M (unit)
       else if andb ((eq_vec (p1_) (('b"11")))) ((eq_vec (p0_) (('b"01")))) return M (unit) then
         (sail_barrier (Barrier_RISCV_w_rw))
          : M (unit)
       else if andb ((eq_vec (p1_) (('b"10")))) ((eq_vec (p0_) (('b"11")))) return M (unit) then
         (sail_barrier (Barrier_RISCV_rw_r))
          : M (unit)
       else if andb ((eq_vec (p1_) (('b"01")))) ((eq_vec (p0_) (('b"10")))) return M (unit) then
         (sail_barrier (Barrier_RISCV_r_w))
          : M (unit)
       else if andb ((eq_vec (p1_) (('b"10")))) ((eq_vec (p0_) (('b"01")))) return M (unit) then
         (sail_barrier (Barrier_RISCV_w_r))
          : M (unit)
       else returnM ((if eq_vec (p1_) (('b"00")) then tt else tt)))
       : M (unit)
   end >>
   (generate_event (EV_FENCE)) >> returnM (RETIRE_SUCCESS).

