Definition execute_AMO
(op : amoop) (aq : bool) (rl : bool) (rs2 : regidx) (rs1 : regidx) (width : Z) (rd : regidx)
(*member_Z_list width [1; 2; 4; 8; 16]*)
: M (ExecutionResult) :=
   catch_early_return
     (let width := width in
     liftR (assert_exp' (Z.leb (width) ((Z.mul (xlen_bytes) (2)))) "extensions/A/zaamo_insts.sail:73.32-73.33") >>= fun _ =>
     let access := Atomic ((op, aq, rl, Data, Data)) in
