     let eff_priv := access_info.(AccessInfo_eff_privilege) in
     liftR ((get_transformed_data_addr (rs1) ((zeros' (64))) (access) (access_info) (width))) >>= fun (w__0 : Ext_DataAddr_Check unit) =>
     match w__0 with
     | Ext_DataAddr_Error e =>
        (early_return ((Ext_DataAddr_Check_Failure (e))
         : ExecutionResult) :
          MR ExecutionResult virtaddr)
         : MR (ExecutionResult) (virtaddr)
     | Ext_DataAddr_OK vaddr => returnR (ExecutionResult) (vaddr)
     end >>= fun (vaddr : virtaddr) =>
     (if not ((is_aligned_vaddr (vaddr) (width))) return MR (ExecutionResult) (unit) then
        match plat_misaligned_exception (access) (false) with
        | Some AccessFault =>
