            : MR (ExecutionResult) (unit)) >>
        returnR (ExecutionResult) (RETIRE_SUCCESS)
      else
        liftR ((mem_write_value (addr) (width)
                  ((sign_extend' ((Z.mul (8) ((__id (width))))) (result'))) (eff_priv) (access)
                  (pbmt) ((andb (aq) (rl))) (rl) (true))) >>= fun (w__20 : result bool ((physaddr * ExceptionType))) =>
        match w__20 with
        | Ok true =>
           (if Z.leb (width) (xlen_bytes) return MR (ExecutionResult) (unit) then
              liftR ((wX_bits (rd) ((sign_extend' (64) (loaded)))))
               : MR (ExecutionResult) (unit)
            else
              liftR ((wX_pair_bits (rd) ((sign_extend' ((Z.mul (64) (2))) (loaded)))))
               : MR (ExecutionResult) (unit)) >>
           returnR (ExecutionResult) (RETIRE_SUCCESS)
        | Ok false =>
           liftR ((internal_error ("extensions/A/zaamo_insts.sail") (155)
                     ("AMO got false from mem_write_value")))
            : MR (ExecutionResult) (ExecutionResult)
        | Err (exc_addr, e) =>
           liftR (assert_exp (generic_eq (exc_addr) (addr)) "extensions/A/zaamo_insts.sail:158.29-158.30") >>
           liftR ((memory_exception (e) ((bits_of_virtaddr (vaddr))) (access_info)))
            : MR (ExecutionResult) (ExecutionResult)
        end
         : MR (ExecutionResult) (ExecutionResult))
      : MR (ExecutionResult) (ExecutionResult)).

Definition execute_AES64KS2 (rs2 : regidx) (rs1 : regidx) (rd : regidx) : M (ExecutionResult) :=
   assert_exp' (Z.eqb (xlen) (64)) "extensions/K/zkn_insts.sail:343.19-343.20" >>= fun _ =>
   (rX_bits (rs1)) >>= fun (w__0 : mword 64) =>
   (rX_bits (rs2)) >>= fun (w__1 : mword 64) =>
   let w0 : bits 32 :=
     xor_vec ((subrange_vec_dec (w__0) (63) (32))) ((subrange_vec_dec (w__1) (31) (0))) in
   (rX_bits (rs1)) >>= fun (w__2 : mword 64) =>
   (rX_bits (rs2)) >>= fun (w__3 : mword 64) =>
   (rX_bits (rs2)) >>= fun (w__4 : mword 64) =>
   let w1 : bits 32 :=
     xor_vec ((subrange_vec_dec (w__2) (63) (32)))
       ((xor_vec ((subrange_vec_dec (w__3) (31) (0))) ((subrange_vec_dec (w__4) (63) (32))))) in
   (wX_bits (rd) ((concat_vec (w1) (w0)))) >> returnM (RETIRE_SUCCESS).

