Definition execute (merge_var : instruction) : M (ExecutionResult) :=
   match merge_var with
   | ZICBOP (cbop, rs1, offset) => (execute_ZICBOP (cbop) (rs1) (offset))  : M (ExecutionResult)
   | NTL g__8 => returnM ((execute_NTL (g__8)))
   | C_NTL g__9 => returnM ((execute_C_NTL (g__9)))
   | PAUSE arg0 => returnM ((execute_PAUSE (arg0)))
   | LPAD lpl => (execute_LPAD (lpl))  : M (ExecutionResult)
   | UTYPE (imm, rd, op) => (execute_UTYPE (imm) (rd) (op))  : M (ExecutionResult)
   | JAL (imm, rd) => (execute_JAL (imm) (rd))  : M (ExecutionResult)
   | BTYPE (imm, rs2, rs1, op) => (execute_BTYPE (imm) (rs2) (rs1) (op))  : M (ExecutionResult)
   | ITYPE (imm, rs1, rd, op) => (execute_ITYPE (imm) (rs1) (rd) (op))  : M (ExecutionResult)
   | SHIFTIOP (shamt, rs1, rd, op) =>
      (execute_SHIFTIOP (shamt) (rs1) (rd) (op))  : M (ExecutionResult)
   | RTYPE (rs2, rs1, rd, op) => (execute_RTYPE (rs2) (rs1) (rd) (op))  : M (ExecutionResult)
   | LOAD (imm, rs1, rd, is_unsigned, width) =>
      (execute_LOAD (imm) (rs1) (rd) (is_unsigned) (width))  : M (ExecutionResult)
   | STORE (imm, rs2, rs1, width) =>
      (execute_STORE (imm) (rs2) (rs1) (width))  : M (ExecutionResult)
   | ADDIW (imm, rs1, rd) => (execute_ADDIW (imm) (rs1) (rd))  : M (ExecutionResult)
   | RTYPEW (rs2, rs1, rd, op) => (execute_RTYPEW (rs2) (rs1) (rd) (op))  : M (ExecutionResult)
   | SHIFTIWOP (shamt, rs1, rd, op) =>
      (execute_SHIFTIWOP (shamt) (rs1) (rd) (op))  : M (ExecutionResult)
   | FENCE_TSO arg0 => (execute_FENCE_TSO (arg0))  : M (ExecutionResult)
   | FENCE (_fm, pred, succ, _rs, _rd) =>
      (execute_FENCE (_fm) (pred) (succ) (_rs) (_rd))  : M (ExecutionResult)
   | ECALL arg0 => (execute_ECALL (arg0))  : M (ExecutionResult)
   | MRET arg0 => (execute_MRET (arg0))  : M (ExecutionResult)
   | SRET arg0 => (execute_SRET (arg0))  : M (ExecutionResult)
   | EBREAK arg0 => (execute_EBREAK (arg0))  : M (ExecutionResult)
   | WFI arg0 => (execute_WFI (arg0))  : M (ExecutionResult)
   | SFENCE_VMA (rs1, rs2) => (execute_SFENCE_VMA (rs1) (rs2))  : M (ExecutionResult)
   | JALR (imm, rs1, rd) => (execute_JALR (imm) (rs1) (rd))  : M (ExecutionResult)
   | AMO (op, aq, rl, rs2, rs1, width, rd) =>
      (execute_AMO (op) (aq) (rl) (rs2) (rs1) (width) (rd))  : M (ExecutionResult)
   | LOADRES (aq, rl, rs1, width, rd) =>
      (execute_LOADRES (aq) (rl) (rs1) (width) (rd))  : M (ExecutionResult)
   | STORECON (aq, rl, rs2, rs1, width, rd) =>
      (execute_STORECON (aq) (rl) (rs2) (rs1) (width) (rd))  : M (ExecutionResult)
   | MUL (rs2, rs1, rd, mul_op) => (execute_MUL (rs2) (rs1) (rd) (mul_op))  : M (ExecutionResult)
   | DIV (rs2, rs1, rd, is_unsigned) =>
      (execute_DIV (rs2) (rs1) (rd) (is_unsigned))  : M (ExecutionResult)
   | REM (rs2, rs1, rd, is_unsigned) =>
      (execute_REM (rs2) (rs1) (rd) (is_unsigned))  : M (ExecutionResult)
   | MULW (rs2, rs1, rd) => (execute_MULW (rs2) (rs1) (rd))  : M (ExecutionResult)
   | DIVW (rs2, rs1, rd, is_unsigned) =>
      (execute_DIVW (rs2) (rs1) (rd) (is_unsigned))  : M (ExecutionResult)
   | REMW (rs2, rs1, rd, is_unsigned) =>
      (execute_REMW (rs2) (rs1) (rd) (is_unsigned))  : M (ExecutionResult)
   | SLLIUW (shamt, rs1, rd) => (execute_SLLIUW (shamt) (rs1) (rd))  : M (ExecutionResult)
   | ZBA_RTYPEUW (rs2, rs1, rd, shamt) =>
      (execute_ZBA_RTYPEUW (rs2) (rs1) (rd) (shamt))  : M (ExecutionResult)
   | ZBA_RTYPE (rs2, rs1, rd, shamt) =>
      (execute_ZBA_RTYPE (rs2) (rs1) (rd) (shamt))  : M (ExecutionResult)
   | RORIW (shamt, rs1, rd) => (execute_RORIW (shamt) (rs1) (rd))  : M (ExecutionResult)
   | RORI (shamt, rs1, rd) => (execute_RORI (shamt) (rs1) (rd))  : M (ExecutionResult)
   | ZBB_RTYPEW (rs2, rs1, rd, op) =>
      (execute_ZBB_RTYPEW (rs2) (rs1) (rd) (op))  : M (ExecutionResult)
   | ZBB_RTYPE (rs2, rs1, rd, op) =>
      (execute_ZBB_RTYPE (rs2) (rs1) (rd) (op))  : M (ExecutionResult)
   | ZBB_EXTOP (rs1, rd, op) => (execute_ZBB_EXTOP (rs1) (rd) (op))  : M (ExecutionResult)
   | REV8 (rs1, rd) => (execute_REV8 (rs1) (rd))  : M (ExecutionResult)
   | ORCB (rs1, rd) => (execute_ORCB (rs1) (rd))  : M (ExecutionResult)
   | CPOP (rs1, rd) => (execute_CPOP (rs1) (rd))  : M (ExecutionResult)
   | CPOPW (rs1, rd) => (execute_CPOPW (rs1) (rd))  : M (ExecutionResult)
