   | E_SAMO_Addr_Align tt => sys_misaligned_samo_writes_tinst
   | E_SAMO_Access_Fault tt => sys_samo_access_fault_writes_tinst
   | E_Load_Page_Fault tt => sys_load_page_fault_writes_tinst
   | E_SAMO_Page_Fault tt => sys_samo_page_fault_writes_tinst
   | E_Load_GPage_Fault tt => sys_load_guest_page_fault_writes_tinst
   | E_SAMO_GPage_Fault tt => sys_samo_guest_page_fault_writes_tinst
   | _ => false
   end.

