Definition wait_is_nop (wr : WaitReason) : bool :=
   match wr with | WAIT_WFI => false | WAIT_WRS_STO => false | WAIT_WRS_NTO => false end.

Definition try_step (step_no : Z) (exit_wait : bool) (*0 <=? step_no*) : M (bool) :=
   let '(_) := (ext_pre_step_hook (tt))  : unit in
   (update_mip (tt)) >>
   read_reg cur_privilege >>= fun (w__0 : Privilege) =>
   (should_inc_minstret (w__0)) >>= fun (w__1 : bool) =>
   write_reg minstret_increment w__1 >>
   read_reg hart_state >>= fun (w__2 : HartState) =>
   match w__2 with
   | HART_WAITING (wr, instr_info) =>
      (run_hart_waiting (step_no) (wr) (instr_info) (exit_wait))  : M (Step)
   | HART_ACTIVE tt => (run_hart_active (step_no))  : M (Step)
   end >>= fun (step_val : Step) =>
   match step_val with
   | Step_Pending_Trigger (action, _, trigger_tval) =>
      match action with
      | TA_Breakpoint =>
         (exception_context ((E_Breakpoint (Brk_Hardware))) (trigger_tval)) >>= fun (w__5 : ExceptionContext) =>
         (handle_exception (w__5))
          : M (unit)
      | _ =>
         (internal_error ("postlude/step.sail") (268)
            ((String.append ("Trigger action ")
                ((String.append ((trigger_action_name_forwards (action))) (" not supported."))))))
          : M (unit)
      end
       : M (unit)
   | Step_Pending_Interrupt (intr, priv) =>
      let '(_) :=
        (if get_config_print_instr (tt) then
           print_bits ("Handling interrupt: ") ((interruptType_bits_forwards (intr)))
         else tt)
         : unit in
      (handle_interrupt (intr) (priv))
       : M (unit)
   | Step_Ext_Fetch_Failure e => returnM ((ext_handle_fetch_check_error (e)))
   | Step_Fetch_Failure e => (handle_exception (e))  : M (unit)
   | Step_Waiting _ =>
      read_reg hart_state >>= fun (w__6 : HartState) =>
      (assert_exp (hart_is_waiting (w__6)) "cannot be Waiting in a non-Wait state")
       : M (unit)
   | Step_Execute (Retire_Success tt, instr_info) =>
      read_reg hart_state >>= fun (w__7 : HartState) =>
      assert_exp (hart_is_active (w__7)) "postlude/step.sail:280.39-280.40" >>
      (match_icount_triggers (instr_info.(instr_info_fetch_privilege))
         (instr_info.(instr_info_fetch_trigger_reentrance)))
       : M (unit)
   | Step_Execute (ExecuteAs _, _) =>
      (internal_error ("postlude/step.sail") (286)
         ("Multiple chained ExecuteAs (only one redirection is supported)."))
       : M (unit)
   | Step_Execute (Trap (priv, ctx, pc), instr_info) =>
      (transform_exception_context (ctx) (instr_info)) >>= fun ctx =>
      (exception_handler (priv) (ctx) (pc)) >>= fun (w__8 : mword 64) =>
      (set_next_pc (w__8))
       : M (unit)
   | Step_Execute (Illegal_Instruction tt, instr_info) =>
      (handle_exception
         ((make_instr_exception_context ((E_Illegal_Instr (tt)))
             ((zero_extend' (64) (instr_info.(instr_info_instbits)))))))
       : M (unit)
   | Step_Execute (Virtual_Instruction tt, instr_info) =>
      (handle_exception
         ((make_instr_exception_context ((E_Virtual_Instr (tt)))
             ((zero_extend' (64) (instr_info.(instr_info_instbits)))))))
       : M (unit)
   | Step_Execute (Enter_Wait wr, instr_info) =>
      (if wait_is_nop (wr) return M (unit) then
         read_reg hart_state >>= fun (w__9 : HartState) =>
         assert_exp (hart_is_active (w__9)) "postlude/step.sail:299.41-299.42" >>
         (match_icount_triggers (instr_info.(instr_info_fetch_privilege))
            (instr_info.(instr_info_fetch_trigger_reentrance)))
          : M (unit)
       else
         (if get_config_print_instr (tt) return M (unit) then
            ((read_reg PC)  : M (mword 64)) >>= fun (w__10 : mword 64) =>
            returnM ((print_endline
                        ((String.append ("entering ")
                            ((String.append ((wait_name_forwards (wr)))
                                ((String.append (" state at PC ") ((string_of_bits (w__10)))))))))))
          else returnM (tt)) >>
         write_reg hart_state (HART_WAITING ((wr, instr_info)))
          : M (unit))
       : M (unit)
   | Step_Execute (Ext_CSR_Check_Failure tt, _) => returnM ((ext_check_CSR_fail (tt)))
   | Step_Execute (Ext_ControlAddr_Check_Failure e, _) =>
      returnM ((ext_handle_control_check_error (e)))
   | Step_Execute (Ext_DataAddr_Check_Failure e, _) => returnM ((ext_handle_data_check_error (e)))
   | Step_Execute (Ext_XRET_Priv_Failure tt, _) => returnM ((ext_fail_xret_priv (tt)))
   end >>
   read_reg hart_state >>= fun (w__11 : HartState) =>
   match w__11 with
   | HART_WAITING _ => returnM (true)
   | HART_ACTIVE tt =>
      (tick_pc (tt)) >>
      let retired : bool :=
        match step_val with
        | Step_Execute (Retire_Success tt, g__0) => true
        | Step_Execute (Enter_Wait wr, g__1) => if wait_is_nop (wr) then true else false
        | _ => false
        end in
      (and_boolM (returnM (retired)) (read_reg minstret_increment  : M (bool))) >>= fun w__13 =>
      (if w__13 return M (unit) then
         ((read_reg minstret)  : M (mword 64)) >>= fun (w__14 : mword 64) =>
         write_reg minstret (add_vec_int (w__14) (1))
          : M (unit)
       else returnM (tt)) >>
      (dispatch_events (tt)) >>
      (clear_written_event_index (tt)) >>
      (update_triggers (tt)) >>
      (if get_config_rvfi (tt) return M (unit) then
         ((read_reg rvfi_pc_data)  : M (mword 128)) >>= fun (w__15 : mword 128) =>
         (get_arch_pc (tt)) >>= fun (w__16 : mword 64) =>
         write_reg
           rvfi_pc_data
           (update_subrange_vec_dec (w__15) (127) (64) ((zero_extend' (64) (w__16))))
          : M (unit)
       else returnM (tt)) >>
      let '(_) := (ext_post_step_hook (tt))  : unit in
      let '(_) := (if retired then instret_callback (tt) else tt)  : unit in
      returnM (false)
   end
    : M (bool).

Definition loop '(tt : unit) : M (Z) :=
   let i : Z := 0 in
   let step_no : Z := 0 in
   (whileMT
     (i, step_no)
     (fun '(i, step_no) => 100)
     (fun '(i, step_no) =>
       (read_reg htif_done >>= fun (w__0 : bool) => returnM (((not (w__0))  : bool)))
        : M (bool))
     (fun '(i, step_no) =>
       (assert_exp' true "loop dummy assert" >>= fun _ =>
        (try_step (step_no) (true)) >>= fun stepped =>
        (if stepped return M (Z) then
           let step_no : Z := Z.add (step_no) (1) in
           let '(_) := (if get_config_print_instr (tt) then print_step (tt) else tt)  : unit in
           (cycle_count (tt)) >> returnM (step_no)
         else returnM (step_no)) >>= fun (step_no : Z) =>
        read_reg htif_done >>= fun (w__1 : bool) =>
        (if not (w__1) return M (Z) then
           let i : Z := Z.add (i) (1) in
           (if Z.eqb (i) (plat_insns_per_tick) return M (Z) then (tick_clock (tt)) >> returnM (0)
            else returnM (i))
            : M (Z)
         else returnM (i)) >>= fun (i : Z) =>
        returnM ((i, step_no)))
        : M ((Z * Z)))) >>= fun '((i, step_no)
   : (Z * Z)) =>
   ((read_reg htif_exit_code)  : M (mword 64)) >>= fun (w__2 : mword 64) =>
   let exit_val := uint (w__2) in
   let '(_) :=
     (if Z.eqb (exit_val) (0) then print_endline ("SUCCESS")
      else print_int ("FAILURE: ") (exit_val))
      : unit in
   returnM (exit_val).

