Fixpoint check_pma_regions
(regions : list PMA_Region) (prev_base : mword 64) (prev_size : mword 64)
(check_opts : pma_check_opts) (found_valid_svadu_pma : bool)
: bool :=
   pure_early_return
     (match regions with
     | [] =>
        inr ((if andb (check_opts.(pma_check_opts_svadu)) ((not (found_valid_svadu_pma))) then
                let '(_) :=
                  (print_endline
                     ("The Svadu extension is enabled but no memory region supports hardware page-table writes: Svadu requires at least one region provide this support."))
                   : unit in
                false
              else true))
     | region :: rest =>
        (if zopz0zI_u (region.(PMA_Region_base)) ((add_vec (prev_base) (prev_size))) then
           let '(_) :=
             (print_endline
                ((String.append ("Memory region starting at ")
                    ((String.append ((string_of_bits (region.(PMA_Region_base))))
                        ((String.append
                            (" is not above the end of the previous region starting at ")
                            ((String.append ((string_of_bits (prev_base)))
                                ((String.append (" and ending at ")
                                    ((String.append
                                        ((string_of_bits ((add_vec (prev_base) (prev_size))))) ("."))))))))))))))
              : unit in
           inr (false)
         else if Z.gtb
                   ((Z.add ((uint (region.(PMA_Region_base)))) ((uint (region.(PMA_Region_size))))))
                   ((pow2 (physaddr_bits))) then
           let '(_) :=
             (print_endline
                ((String.append ("Memory region starting at ")
                    ((String.append ((string_of_bits (region.(PMA_Region_base))))
                        ((String.append (" ends at ")
                            ((String.append
                                ((string_of_bits
                                    ((add_vec (region.(PMA_Region_base)) (region.(PMA_Region_size))))))
                                ((String.append
                                    (" which is above the representable limit of the physical address bit size (i.e. ")
                                    ((String.append ((dec_str (physaddr_bits)))
                                        (" from `memory.physaddr_bits`)."))))))))))))))
              : unit in
           inr (false)
         else if not ((check_pma_region (region))) then inr (false)
         else
           let attributes := region.(PMA_Region_attributes) in
           (if andb ((generic_eq (attributes.(PMA_mem_type)) (MainMemory)))
                 ((andb (attributes.(PMA_cacheable)) (attributes.(PMA_coherent))))
              return
              sum (bool) (unit) then
              let mag := attributes.(PMA_misaligned_atomicity_granule_size_exp) in
              (if andb (check_opts.(pma_check_opts_zama16b)) ((Z.ltb (mag) (4)))
                 return
                 sum (bool) (unit) then
                 let '(_) :=
                   (print_endline
                      ((String.append ("Main memory region starting at ")
                          ((String.append ((string_of_bits (region.(PMA_Region_base))))
                              ((String.append (" is coherent and cacheable with ")
                                  ((String.append
                                      ((if Z.eqb (mag) (0) then
                                          "no specified misaligned atomicity granule PMA"
                                        else
                                          String.append
                                            ("a misaligned atomicity granule size of 2^")
                                            ((dec_str (mag)))))
                                      (", but Zama16b is enabled which requires granule size of at least 2^4 bytes."))))))))))
                    : unit in
                 (inl (false  : bool) : sum bool unit)
                  : sum (bool) (unit)
               else if andb (check_opts.(pma_check_opts_ziccamoa))
                         ((pma_atomicity_support_lt (attributes.(PMA_atomic_support))
                             (AMOArithmetic)))
                 return
                 sum (bool) (unit) then
                 let '(_) :=
                   (print_endline
                      ((String.append ("Main memory region starting at ")
                          ((String.append ((string_of_bits (region.(PMA_Region_base))))
                              ((String.append (" is coherent and cacheable with ")
                                  ((String.append
                                      ((atomic_support_str_forwards
                                          (attributes.(PMA_atomic_support))))
                                      (" atomicity support, but Ziccamoa is enabled which requires AMOArithmetic support."))))))))))
                    : unit in
                 (inl (false  : bool) : sum bool unit)
                  : sum (bool) (unit)
               else if andb (check_opts.(pma_check_opts_ziccamoc))
                         ((generic_neq (attributes.(PMA_atomic_support)) (AMOCASQ)))
                 return
                 sum (bool) (unit) then
                 let '(_) :=
                   (print_endline
                      ((String.append ("Main memory region starting at ")
                          ((String.append ((string_of_bits (region.(PMA_Region_base))))
                              ((String.append (" is coherent and cacheable with ")
                                  ((String.append
                                      ((atomic_support_str_forwards
                                          (attributes.(PMA_atomic_support))))
                                      (" atomicity support, but Ziccamoc is enabled which requires AMOCASQ support."))))))))))
                    : unit in
                 (inl (false  : bool) : sum bool unit)
                  : sum (bool) (unit)
               else if andb (check_opts.(pma_check_opts_ziccif))
                         ((not (attributes.(PMA_executable))))
                 return
                 sum (bool) (unit) then
                 let '(_) :=
                   (print_endline
                      ((String.append ("Memory region starting at ")
                          ((String.append ((string_of_bits (region.(PMA_Region_base))))
                              (" is coherent and cacheable with no instruction fetch support, but Ziccif is enabled which requires this support."))))))
                    : unit in
                 (inl (false  : bool) : sum bool unit)
                  : sum (bool) (unit)
               else
               (if check_opts.(pma_check_opts_zicclsm) return sum (bool) (unit) then
                  (if misaligned_exception_is_access_fault
                        (attributes.(PMA_misaligned_exceptions).(PMAMisalignedExceptions_load_store))
                     return
                     sum (bool) (unit) then
                     let '(_) :=
                       (print_endline
                          ((String.append ("Main memory region starting at ")
